window.CNCT_DATA = {"version":"2026-11-06","language":"en","public":true,"exam_format":{"questions":30,"correct":1,"wrong":-0.33,"blank":0,"duration_min":70,"practice_duration_min":60,"max_written_score":30,"lab_bonus":{"per_lab":0.5,"max":2,"written_threshold":18}},"units":{"01":{"name":"IPv4 and addressing"},"02":{"name":"Routing"},"03":{"name":"IPv6 and transition"},"04":{"name":"LANs and VLANs"},"05":{"name":"Multimedia and quality of service"},"06":{"name":"Cloud computing: concepts and models"},"07":{"name":"Virtualization"},"08":{"name":"Containers"},"09":{"name":"Network softwarization"},"10":{"name":"Labs"}},"questions":[{"id":"001","unit":"01","topic":"Aggregation and CIDR","text":"The networks 192.168.1.0/24 and 192.168.2.0/24 can be aggregated into:","options":{"a":"192.168.0.0/23","b":"0.0.0.0/0","c":"192.168.1.0/23","d":"They cannot be aggregated."},"answer":"d","explanation":"The two /24 prefixes are not adjacent as a /23 CIDR block; /0 would cover almost the whole Internet and is not a useful aggregation of them.","status":"weak"},{"id":"002","unit":"01","topic":"Addressing and subnetting","text":"Two stations A and B belong to the same physical network and have IP addresses 130.192.1.1/25 and 130.192.1.129/24 respectively.","options":{"a":"A communicates directly with B and vice versa","b":"A communicates directly with B but not vice versa","c":"A communicates with B only through a router","d":"A cannot communicate with B"},"answer":"c","explanation":"For A, with /25, B's address is outside its prefix and requires the router; B, with /24, sees A on its own link.","status":"ok"},{"id":"003","unit":"01","topic":"Aggregation and CIDR","text":"Two IP networks 130.192.0.0/24 and 130.192.2.0/24 can be aggregated into:","options":{"a":"130.192.0.0/23","b":"130.192.2.0/23","c":"They cannot be aggregated","d":"130.192.0.0/22"},"answer":"d","explanation":"The smallest prefix containing the networks 0.0/24 and 2.0/24 is 130.192.0.0/22, even though it also includes other networks.","status":"ok"},{"id":"004","unit":"01","topic":"Addressing and subnetting","text":"two stations A and B have 130.192.1.1/25 and 130.192.1.100/24 respectively","options":{"a":"communicates directly with B and vice versa","b":"communicates directly with A but not vice versa","c":"communicates directly with B only through a router","d":"communicates directly with b but not vice versa"},"answer":"a","explanation":"Both addresses are in the block 130.192.1.0/25, so each host sees the other as local.","status":"ok"},{"id":"005","unit":"01","topic":"Aggregation and CIDR","text":"the smallest aggregation that can contain the two IP networks 130.192.0.0/25 and 130.192.1.0/25","options":{"a":"130.192.1.0/23","b":"130.192.0.0/24","c":"130.192.1.0/24","d":"130.192.0.0/23"},"answer":"d","explanation":"The most specific common prefix of 130.192.0.0/25 and 130.192.1.0/25 is 130.192.0.0/23.","status":"ok"},{"id":"006","unit":"01","topic":"Addressing and subnetting","text":"Host A has address 192.168.1.1/24 and host B has 192.168.1.129/25. Which statement is correct?","options":{"a":"Both can communicate directly with each other.","b":"A can communicate directly with B but not vice versa.","c":"A needs a router to communicate with B","d":"They cannot communicate."},"answer":"b","explanation":"A's /24 mask includes B, while B's /25 mask excludes A's address.","status":"ok"},{"id":"007","unit":"01","topic":"ARP and direct delivery","text":"An ARP Request that a host with IP address 130.192.10.1/24 sends to learn the MAC address of a host with IP address 130.192.10.200","options":{"a":"Arrives at the destination if the two hosts are connected by means of an Ethernet switch, ignoring possible failures of links and devices involved","b":"Never arrives at the destination","c":"Actually, the ARP Request is not sent because the destination host is outside the IP network of the source","d":"Always arrives at the destination, ignoring possible failures of links and devices involved"},"answer":"a","explanation":"The ARP Request is a broadcast frame, and a switch in the same LAN forwards it to all the relevant segments.","status":"ok"},{"id":"008","unit":"01","topic":"Aggregation and CIDR","text":"Among the four proposed alternatives, which is the smallest valid aggregation that can represent the IP networks 130.192.1.0/24 and 130.192.2.0/24 in a routing table?","options":{"a":"130.192.1.0/23","b":"0.0.0.0/0","c":"130.192.0.0/23","d":"130.192.0.0/22"},"answer":"d","explanation":"130.192.1.0/24 and 130.192.2.0/24 already differ in the 23rd bit, so no /23 contains both: 130.192.0.0/23 covers only 0.0–1.255 and 130.192.1.0/23 is not a valid (aligned) prefix. The smallest valid block is 130.192.0.0/22.","status":"ok"},{"id":"009","unit":"01","topic":"Addressing and subnetting","text":"Given a network made of several physical networks interconnected by suitable routers, and a range of IP addresses to be used in that network, an addressing plan that optimizes routing on a given router of that network can be obtained:","options":{"a":"By assigning to the physical networks addresses chosen randomly within the address range defined for the network","b":"By assigning to the physical networks addresses chosen within the address range defined for the network, proceeding in decreasing order of network size","c":"By dividing the network into areas and defining, within the initial address range, distinct address ranges to be used in each of those areas"},"answer":"c","explanation":"Assigning contiguous blocks to the areas lets the router aggregate the routes.","status":"ok"},{"id":"010","unit":"01","topic":"ARP and direct delivery","text":"A host A with IP address 130.192.225.79/24 sends an ARP Request on the local network in order to learn the MAC address of a host with IP address 130.192.225.1/26. The corresponding ARP Reply sent from B","options":{"a":"Is sent to the MAC address of B's default gateway, because A is outside the IP network of B","b":"Is not sent","c":"Arrives to A only if the network is based on a shared medium (e.g., a Ethernet hub)","d":"Is sent to the MAC address of A"},"answer":"d","explanation":"The ARP Reply is sent directly to the requester's MAC address, taken from the ARP message, even if the IP masks differ.","status":"weak"},{"id":"011","unit":"02","topic":"Routing concepts","text":"The metric (cost) in a routing algorithm expresses","options":{"a":"The weight to be assigned to a link and used in path selection","b":"The probability that the shortest path is used","c":"The computational complexity of the algorithm"},"answer":"a","explanation":"The metric assigns a cost to links or paths, which is used to choose the route.","status":"weak"},{"id":"012","unit":"02","topic":"Routing concepts","text":"The concepts of Forwarding and Routing:","options":{"a":"Are synonyms; they denote the process that finds a valid path for a packet, from the sender to the receiver","b":"Are synonyms; they denote the process that, for a packet entering a network node, determines the best output port towards the destination","c":"Are different concepts; the forwarding process aims at finding a valid path for a packet, from the sender to the receiver; the routing process, for a packet entering a network node, determines the best output port towards the destination","d":"Are different concepts; the routing process aims at finding a valid path for a packet, from the sender to the receiver; the forwarding process, for a packet entering a network node, determines the best output port towards the destination"},"answer":"d","explanation":"Routing computes the paths; forwarding chooses the output for a packet using the computed information.","status":"ok"},{"id":"013","unit":"02","topic":"Routing concepts","text":"Which of these elements is a significant disadvantage of the centralized routing technique?","options":{"a":"Poor performance when the carried traffic is voice","b":"Difficulty in determining the actual network topology in case of failures","c":"Particularly heavy data traffic around the central node","d":"Criticality of the central node in terms of robustness and scalability"},"answer":"d","explanation":"A central node is a critical point for the robustness and growth of the network.","status":"weak"},{"id":"014","unit":"02","topic":"Path Vector and BGP","text":"The \"Path Vector\" technique makes it possible to:","options":{"a":"Solve the count-to-infinity problem","b":"Solve the problem of overlapping routes","c":"Make the protocol \"transparent\" with respect to the carried information","d":"None of the above"},"answer":"a","explanation":"The path vector carries the path and makes it possible to recognize a path that would re-enter a node already traversed.","status":"ok"},{"id":"015","unit":"02","topic":"Routing concepts","text":"In routing protocols, the transient period:","options":{"a":"is present only when the simplest algorithms are adopted (e.g. Distance Vector)","b":"Is never present, since it is a feature of protocols working at the data-link layer (e.g. Spanning Tree)","c":"Always occurs in the period immediately following the detection of a failure","d":"Always occurs when a part of the network changes its state"},"answer":"d","explanation":"After a change in the network, the information is not updated everywhere instantly: a convergence phase follows.","status":"weak"},{"id":"016","unit":"02","topic":"Routing concepts","text":"In isolated routing:","options":{"a":"Each router computes its own routing table by exchanging messages with its neighbours only","b":"Each router computes its own routing table by exchanging messages with all the routers in the network","c":"Each router computes its own routing table by analysing only the traffic that crosses it","d":"Some portions of the network are isolated from the remaining routers, preventing data transit between the public portion of the network and the isolated one"},"answer":"c","explanation":"In isolated routing each node decides based on locally observed information, without exchanging routes.","status":"ok"},{"id":"017","unit":"02","topic":"Routing concepts","text":"Centralized routing","options":{"a":"Mandates that traffic traverses a specific network node","b":"is an obsolete solution that is never used in modern networks","c":"Mandates that network nodes do not exchange routing information","d":"Consists in one network node computing routes for other network nodes and providing the computed routes to them"},"answer":"d","explanation":"The computation is assigned to a central node, which distributes the routes to the other nodes.","status":"ok"},{"id":"018","unit":"02","topic":"Routing concepts","text":"The static routing","options":{"a":"It is an obsolete technology no longer deployed since dynamic routing is preferred over it","b":"Consists in one network node computing routes for other network nodes and providing the computed routes to them","c":"Consists in the automatic learning of routes without exchanging routing information","d":"Consists in the network administrator manually configuring routing information in each router"},"answer":"d","explanation":"In static routing the entries are configured manually by the administrator.","status":"ok"},{"id":"019","unit":"02","topic":"Path Vector and BGP","text":"In the Path Vector routing algorithm:","options":{"a":"Each record in the Path Vector contains the destination, the distance from the router, and the next-hop router to reach that destination","b":"Each record in the Path Vector contains the destination, the distance from the router, and the next Autonomous System to reach that destination","c":"Each record in the Path Vector contains the destination, the distance from the router, and the list of routers to traverse to reach that destination","d":"Each record in the Path Vector contains the destination, the distance from the router, and the list of Autonomous Systems to traverse to reach that destination"},"answer":"d","explanation":"The BGP path vector records the sequence of Autonomous Systems towards the destination.","status":"ok"},{"id":"020","unit":"02","topic":"Distance Vector","text":"The count-to-infinity phenomenon:","options":{"a":"makes it possible to understand whether a node is no longer reachable","b":"is a variant of the link state algorithm that avoids the creation of loops","c":"is a transient state of the distance vector algorithm","d":"none of the above"},"answer":"c","explanation":"Count to infinity is a transient of distance vector caused by outdated route information.","status":"ok"},{"id":"021","unit":"02","topic":"Distance Vector","text":"The Distance Vector routing algorithm:","options":{"a":"Can cause \"Counting to Infinity\" phenomena only in meshed networks","b":"Always causes \"Counting to Infinity\" phenomena in non-meshed networks","c":"Has a lower chance of \"Counting to Infinity\" phenomena in non-meshed networks when the \"Split Horizon\" technique is used","d":"The \"Counting to Infinity\" phenomenon is typical of Link State networks."},"answer":"c","explanation":"Split horizon reduces two-node loops, but it does not remove every case, especially in meshed topologies.","status":"ok"},{"id":"022","unit":"02","topic":"Distance Vector","text":"The \"Split Horizon\" mechanism makes it possible to:","options":{"a":"Eliminate the possibility of loops (cyclic forwarding paths) after topology changes","b":"Reduce the probability of loops after topology changes","c":"Disable, during the convergence phase, the sending of data packets towards the destinations that could cause loops","d":"Reduce routing traffic by implementing the neighbor discovery phase with dedicated packets (\"Hello Packets\")"},"answer":"b","explanation":"Split horizon reduces the probability of loops by not re-announcing a route to the neighbour it was learned from.","status":"ok"},{"id":"023","unit":"02","topic":"Distance Vector","text":"The \"Split Horizon\" technique:","options":{"a":"Requires that the routes received in the announcements of a neighbouring router are always announced to that neighbour with an infinite metric","b":"Requires that a prefix is not announced to the neighbour that is the \"next hop\" towards that destination","c":"Requires that a destination is declared unreachable when its cost exceeds a certain infinity threshold.","d":"None of the above answers"},"answer":"b","explanation":"A route is not announced to the neighbour that is the next hop of that same route.","status":"ok"},{"id":"024","unit":"02","topic":"Distance Vector","text":"The distance Vector routing algorithm","options":{"a":"Has shorter convergence time when compared to the link state algorithm","b":"Is deployed in specific routing scenarios","c":"Has better stability properties when compared to the link state algorithm","d":"Is outdated and is not any longer used"},"answer":"b","explanation":"Distance vector is still usable in suitable scenarios, despite its convergence limits.","status":"weak"},{"id":"025","unit":"02","topic":"Link State","text":"In the final phase of a Link State routing algorithm, each router:","options":{"a":"Runs the Shortest Path First algorithm, using the Link State Database as input","b":"Floods its own Link States to its neighbours","c":"Floods all the Link States to its neighbours","d":"Runs the DUAL (Diffusing Update Algorithm) algorithm"},"answer":"a","explanation":"After the link states have been spread, each router applies SPF to its own Link State Database.","status":"ok"},{"id":"026","unit":"02","topic":"Link State","text":"The difference between link state and distance vector routing algorithms can be summarized as follows","options":{"a":"Link state algorithms send information about the whole network to all the nodes of the network; distance vector algorithms send information about the local topology only to neighbouring nodes","b":"Link state algorithms send information about the local topology only to neighbouring nodes; distance vector algorithms send information about the whole network to all the nodes","c":"Link state algorithms send information about the local topology to all the nodes of the network; distance vector algorithms send information about the whole network only to neighbouring nodes"},"answer":"c","explanation":"Link state spreads information about the links to all nodes; distance vector exchanges distance vectors with the neighbours.","status":"ok"},{"id":"027","unit":"02","topic":"Link State","text":"What is an advantage of a Link State routing algorithm over a Distance Vector one?","options":{"a":"The Link State Database removes the need for a routing table, saving memory","b":"With the Link State Database available, each router can compute the paths to every destination autonomously","c":"A lower demand for processing power to run the algorithm","d":"Fewer routing errors, because Link States are exchanged by routers very frequently"},"answer":"b","explanation":"The map of the links lets each router compute the paths autonomously.","status":"ok"},{"id":"028","unit":"02","topic":"Link State","text":"Indicate the false claim among the below statements about the Link State algorithm","options":{"a":"The Link State algorithm converges faster than the Distance Vector algorithm","b":"The RIP (Routing Information Protocol) protocol is based on the Link State algorithm","c":"The Link State algorithm seldom generates loops","d":"The Link State algorithm exchanges less information than the Distance Vector algorithm."},"answer":"b","explanation":"RIP is a distance vector protocol, so the claim that it is link state is false.","status":"ok"},{"id":"029","unit":"02","topic":"Link State","text":"Can a loop form in a network that uses Link State routing?","options":{"a":"Yes","b":"No, because each router has a complete view of the network topology","c":"No, because Link State updates are flooded","d":"No, because a Hold-Down timer is used"},"answer":"a","explanation":"The slides say that link state rarely generates loops, not that it rules them out completely.","status":"ok"},{"id":"030","unit":"02","topic":"Autonomous Systems and interdomain routing","text":"An Autonomous System is:","options":{"a":"A computer able to configure itself","b":"A zone of an IP network administered, especially from the routing point of view, independently of the others and with connections to at least two other Autonomous Systems","c":"A network device able to discover autonomously the best path along which to forward packets to the destinations","d":"The network of an ISP"},"answer":"b","explanation":"No option correctly defines every AS: it can be a set of subnets under common management, it does not require at least two neighbouring ASs and it does not necessarily coincide with an ISP.","status":"weak","no_correct_option":true},{"id":"031","unit":"02","topic":"Autonomous Systems and interdomain routing","text":"A Neutral Access Point is a particular network in which:","options":{"a":"All devices are connected through a high-performance central router with multiple network interfaces","b":"The ASs exchange traffic in \"peering\" mode, i.e. free of charge","c":"The connection between the devices is made at layer 2","d":"Each connected router sees at layer 3 all the other routers on the network and is able to peer with each of them"},"answer":"c","explanation":"The NAP is a LAN shared by routers belonging to different ASs; the common connection is at layer 2.","status":"weak"},{"id":"032","unit":"02","topic":"Autonomous Systems and interdomain routing","text":"A Neutral Access Point is a network in which:","options":{"a":"Several Autonomous Systems connect, at layer 2, a number of routers in order to exchange routing information","b":"Several Autonomous Systems connect, at layer 3, a number of routers in order to exchange routing information","c":"An Autonomous System connects, at layer 2, a number of routers in order to speed up the exchange of routing information within the domain","d":"An Autonomous System connects, at layer 3, a number of routers in order to speed up the exchange of routing information within the domain"},"answer":"a","explanation":"Routers of different ASs connect to the NAP through a layer-2 LAN to exchange traffic and routing information.","status":"ok"},{"id":"033","unit":"02","topic":"Autonomous Systems and interdomain routing","text":"Redistribution:","options":{"a":"is the process that must be enabled on the router so that it can dispatch packets towards the right destination","b":"is used to exchange information between an internal router (interior gateway) and an external router (exterior gateway) that uses the BGP protocol","c":"Is used mostly by peripheral routing domains, which connect to a single Internet service provider for Internet access","d":"is used to let routing information pass from a routing domain A to a routing domain B"},"answer":"d","explanation":"Redistribution passes routing information between routing domains or routing protocols.","status":"ok"},{"id":"034","unit":"02","topic":"Autonomous Systems and interdomain routing","text":"redistribution in the context of routing protocols consists in","options":{"a":"distributing the routing table over several devices so as to reduce the memory used on each device","b":"redistributing traffic over several alternative paths to fully exploit network resources and avoid congestion on specific paths","c":"announcing through one routing protocol routes learned with another, even though this results in a loss of information","d":"learning how to reach destinations without having to exchange routing information with other computers"},"answer":"c","explanation":"Routes learned through one protocol are announced with another, with a possible loss of detail.","status":"weak"},{"id":"035","unit":"02","topic":"Autonomous Systems and interdomain routing","text":"Inter-domain routing:","options":{"a":"Requires every router to know exactly the path, in terms of traversed routers, followed by packets towards a destination","b":"Requires an exterior gateway to make path choices, based on information collected through inter-domain routing protocols, consistent with the existing agreements with other autonomous systems","c":"Requires every router to know exactly the cost of reaching any destination (e.g. in terms of bandwidth of the traversed links) in order to compute the lowest-cost path (e.g. the highest-bandwidth one)","d":"is a concept that will tend to disappear"},"answer":"b","explanation":"In inter-domain routing, route selection also follows the policies and agreements between ASs.","status":"ok"},{"id":"036","unit":"02","topic":"Autonomous Systems and interdomain routing","text":"An Autonomous System:","options":{"a":"is identified by means of a 4 bytes long ID assigned by the CSA","b":"is a set of subnets with a short topological proximity and managed by a single organization unit","c":"is a subnet configured by leveraging the static routing","d":"is identified by means of a 4 bytes long ID automatically computed by the BGP"},"answer":"b","explanation":"An AS groups subnets according to topology and organizational criteria under common management.","status":"ok"},{"id":"037","unit":"02","topic":"RIP, IGRP and OSPF","text":"The RIP protocol includes mechanisms to reduce the possibility of loops:","options":{"a":"By analysing the packets in transit and identifying those that pass more than once through the same router","b":"By means of \"traceroute\" processes activated periodically","c":"Through \"Split-Horizon\" and \"Hold-Down\" mechanisms","d":"None of the above answers"},"answer":"c","explanation":"RIP uses techniques such as split horizon and hold down to mitigate loops.","status":"weak"},{"id":"038","unit":"02","topic":"RIP, IGRP and OSPF","text":"The RIP protocol is characterized by","options":{"a":"The use of the link state routing algorithm","b":"The possibility of being used for both inter-domain and intra-domain routing","c":"The ability to operate on large networks thanks to its ability to work hierarchically","d":"Frequent instability and a tendency to create circular forwarding paths"},"answer":"d","explanation":"RIP is distance vector and can converge slowly or produce temporary loops.","status":"ok"},{"id":"039","unit":"02","topic":"RIP, IGRP and OSPF","text":"The main limitation of the RIP routing protocol compared with IGRP is that:","options":{"a":"Since RIP is proprietary, it is not available on all routers","b":"The RIP metric is less representative than the IGRP one of how preferable a network path really is compared with others","c":"Unlike IGRP, it does not allow hierarchical routing","d":"it is a Distance Vector protocol, hence less scalable than IGRP (Link State)"},"answer":"b","explanation":"RIP uses the hop count; IGRP also considers delay, bandwidth and other metrics.","status":"ok"},{"id":"040","unit":"02","topic":"RIP, IGRP and OSPF","text":"RIP, a characteristic:","options":{"a":"It needs to be configured by the administrator in order to work","b":"It exchanges information with neighbouring routers","c":"It can detect the IP addresses of the connected hosts and communicate them to neighbouring routers"},"answer":"b","explanation":"RIP periodically exchanges distance vectors with neighbouring routers.","status":"ok"},{"id":"041","unit":"02","topic":"RIP, IGRP and OSPF","text":"In the OSPF protocol, at steady state all routers store:","options":{"a":"The same tree of optimal paths","b":"The database describing the area they belong to","c":"The same database describing the whole AS","d":"A set of Distance Vectors of all adjacent routers"},"answer":"b","explanation":"With OSPF each router keeps the link-state database of its own area.","status":"weak"},{"id":"042","unit":"02","topic":"RIP, IGRP and OSPF","text":"A difference between the OSPF routing protocol and IGRP is that:","options":{"a":"OSPF is hierarchical","b":"OSPF also allows routing between different ASs","c":"OSPF can carry at the same time routing information for different protocol architectures (integrated routing)","d":"OSPF is proprietary"},"answer":"a","explanation":"OSPF divides the domain into areas and supports hierarchical routing.","status":"ok"},{"id":"043","unit":"02","topic":"Path Vector and BGP","text":"The BGP routing protocol:","options":{"a":"Uses rules (policies) on information in addition to cost metrics to identify the \"best\" path to reach a destination","b":"is used exclusively to exchange information between routers of different autonomous systems","c":"is used exclusively to exchange information between routers of the same autonomous system","d":"is the protocol that will replace OSPF"},"answer":"a","explanation":"BGP considers attributes and policies, beyond the simple cost metric.","status":"ok"},{"id":"044","unit":"02","topic":"Path Vector and BGP","text":"The BGP protocol is used in the Internet for","options":{"a":"Exchanging information between routers belonging to different autonomous systems","b":"Communicating the state of a router's links to bordering routers","c":"Discovering neighbouring routers (bordering routers) on a local network","d":"Finding the geographical position of a host from its IP address"},"answer":"a","explanation":"BGP is the protocol used to exchange reachability information between ASs.","status":"ok"},{"id":"045","unit":"02","topic":"Path Vector and BGP","text":"In the BGP routing protocol:","options":{"a":"Topology information always takes precedence over the application of routing policies","b":"The application of routing policies always takes precedence over topology information","c":"The lowest-cost path to each destination is always chosen","d":"The lowest-cost path to each destination is always chosen, except for limitations intrinsic to hierarchical routing"},"answer":"b","explanation":"The BGP choice can follow agreements and policies even when another route would be shorter.","status":"ok"},{"id":"046","unit":"02","topic":"Path Vector and BGP","text":"The \"Path Vector\" technique used by BGP:","options":{"a":"Stores in the Path Vectors the list of Autonomous Systems to traverse to reach a given destination network","b":"Stores in the Path Vectors the list of routers to traverse to reach a given destination network","c":"Stores in the Path Vectors the next Autonomous System to traverse to reach a given destination network","d":"Stores in the Path Vectors the next router to traverse to reach a given destination network"},"answer":"a","explanation":"The AS path is the sequence of ASs traversed towards the announced network.","status":"ok"},{"id":"047","unit":"03","topic":"IPv6 header and comparison with IPv4","text":"Unlike version 4 of IP, version 6:","options":{"a":"Has no associated version of ICMP.","b":"Does not allow discovering the MAC address of another station from its IP address.","c":"Has no broadcast addresses.","d":"Has no equivalent of the TTL (time-to-live) field."},"answer":"c","explanation":"IPv6 does not use broadcast addresses; it uses multicast and other specific mechanisms.","status":"weak"},{"id":"048","unit":"03","topic":"IPv6 header and comparison with IPv4","text":"IPv6 header","options":{"a":"The header has a fixed size and no options can be added","b":"The header has a variable size","c":"Fixed header size, but additional headers can possibly be added(?)"},"answer":"c","explanation":"The base IPv6 header has a fixed size and can be followed by extension headers.","status":"ok"},{"id":"049","unit":"03","topic":"IPv6 addresses","text":"A link-local address:","options":{"a":"Can be used to allow communication between stations on local links (e.g. a LAN) when no other IPv6 addresses are available.","b":"Is used to physically connect two stations on a local link.","c":"Is the address used by the stations on a LAN to exchange data.","d":"Is used in all communications between local stations."},"answer":"a","explanation":"FE80::/64 serves communications on the single link, even without other addresses.","status":"ok"},{"id":"050","unit":"03","topic":"Neighbor Discovery","text":"The Neighbor Discovery procedures in IPv6","options":{"a":"are based on ARPv6","b":"are based on an ICMPv6 packet sent in broadcast","c":"are based on an ICMPv6 packet sent in multicast","d":"require the network to also support IPv4"},"answer":"c","explanation":"Neighbor Discovery uses ICMPv6 messages sent in multicast to the solicited-node group.","status":"ok"},{"id":"051","unit":"03","topic":"IPv6 addresses","text":"IPv6 Aggregatable Global Unicast addresses are:","options":{"a":"Aggregatable only in very small address ranges, so as to improve the precision of path computation","b":"Globally unique, essentially equivalent to IPv4 public addresses","c":"Usable only on devices belonging to the same local network","d":"Usable globally only together with suitable Network Address Translation (NAT) techniques"},"answer":"b","explanation":"Aggregatable global unicast addresses are globally reachable, like public IPv4 addresses.","status":"ok"},{"id":"052","unit":"03","topic":"Neighbor Discovery","text":"The Solicited Node Multicast Address is:","options":{"a":"The multicast address used as source address in a Neighbor Solicitation packet","b":"The multicast address placed in the payload (Target Address field of ARPv6) of a Neighbor Solicitation packet","c":"The multicast address placed in the payload (Target Address field of ICMPv6) of a Neighbor Solicitation packet","d":"The multicast address used as destination address in a Neighbor Solicitation packet"},"answer":"d","explanation":"The Neighbor Solicitation is sent to the solicited-node multicast address of the target.","status":"ok"},{"id":"053","unit":"03","topic":"IPv6 addresses","text":"The IPv6 addressing scheme:","options":{"a":"Includes only addresses assigned uniquely by a dedicated authority.","b":"Requires each entity (e.g. a company) to obtain globally a set of addresses, which become its property for an unlimited time.","c":"Requires the first 64 bits of an address to be normally identified as the network prefix, at least on LANs.","d":"Does not include multicast addresses."},"answer":"c","explanation":"On LANs the IPv6 prefix is normally 64 bits long; the remaining bits identify the interface.","status":"ok"},{"id":"054","unit":"03","topic":"IPv6 addresses","text":"aggregatable global unicast addresses","options":{"a":"Can be used only by routers","b":"Can be used only by hosts","c":"Are distributed geographically in a hierarchical way"},"answer":"c","explanation":"The assignment is hierarchical and topology-based; the adverb \"geographically\" in the answer is imprecise.","status":"weak"},{"id":"055","unit":"03","topic":"IPv6 addresses","text":"The IPv6 address FE80::0201:06FF:FEA5:3A4C is:","options":{"a":"An address that a host with MAC address 00:01:06:A5:3A:4C can use to communicate with another host on the same link","b":"An address that a server with MAC address 00:01:06:A5:3A:4C can use to offer a service on the public IPv6 Internet","c":"An address that can be used by several devices on the same link","d":"An address currently not foreseen in IPv6"},"answer":"a","explanation":"FE80 is link-local, and the interface ID shown is derived from the given MAC through EUI-64.","status":"ok"},{"id":"056","unit":"03","topic":"Neighbor Discovery","text":"The forwarding of IPv6 packets on a LAN:","options":{"a":"Does not use neighbor discovery mechanisms, since there is a rule to map any IPv6 address into a MAC address.","b":"Does not use neighbor discovery mechanisms for the forwarding of multicast and broadcast IPv6 packets, since there is a rule to map these IPv6 addresses into a MAC address.","c":"Uses neighbor discovery mechanisms for all types of IPv6 addresses.","d":"Does not use neighbor discovery mechanisms for the forwarding of multicast IPv6 packets, since there is a rule to map these IPv6 addresses into a MAC address."},"answer":"d","explanation":"IPv6 multicast is mapped algorithmically onto Ethernet; unicast requires Neighbor Discovery.","status":"ok"},{"id":"057","unit":"03","topic":"IPv6 addresses","text":"IPv6 addresses","options":{"a":"Allow IPv6 stations to communicate with IPv4 stations without any additional mechanism.","b":"Keep the same flexible split between a network part and a host part already present in IPv4.","c":"Are rigidly partitioned into a network, subnetwork and host part.","d":"Are rigidly partitioned into a network part and a host part."},"answer":"b","explanation":"The prefix length can vary, although /64 is the normal choice on LANs.","status":"ok"},{"id":"058","unit":"03","topic":"IPv6 header and comparison with IPv4","text":"The IPv6 protocol requires the header of IP packets to:","options":{"a":"Always be authenticated through suitable cryptographic algorithms to increase the security of transmissions","b":"Be smaller than the header of IPv4 packets, so as to use the transmission bandwidth more efficiently by reducing the protocol overhead","c":"Consist only of fixed-length fields carrying the information needed in every packet","d":"Include some fields, previously available only as IPv4 options, for features that turned out to be widely used over time."},"answer":"c","explanation":"The base header contains the required fixed fields; optional functions go into the extension headers.","status":"ok"},{"id":"059","unit":"03","topic":"IPv6 header and comparison with IPv4","text":"Unlike version 4 of IP, version 6:","options":{"a":"Has no variable-length header.","b":"Does not allow discovering the MAC address of another station from its IP address.","c":"Has no equivalent of the TTL (time-to-live).","d":"Does not allow the use of IPsec."},"answer":"a","explanation":"The base IPv6 header has a fixed length, unlike the IPv4 one.","status":"ok"},{"id":"060","unit":"03","topic":"IPv6 header and comparison with IPv4","text":"The IPv6 Extension Headers are","options":{"a":"Header chains that can be added to the main IPv6 header in order to move to the network layer some features that are typically of the transport layer (e.g., the transmission of acknowledges)","b":"Padding techniques adopted to make the IPv6 packet of fixed size equal to 40 bytes","c":"Header chains that can be added to the main IPv6 header in order to offer additional features","d":"Padding techniques adopted to fix the size of the layer 2 frame containing the IPv6 packet"},"answer":"c","explanation":"Chained extension headers add features to the base header.","status":"ok"},{"id":"061","unit":"03","topic":"IPv6 header and comparison with IPv4","text":"In IPv6, which field disappears from the base header compared with IPv4?","options":{"a":"The packet time to live.","b":"The source and destination addresses.","c":"The indication of which header comes next.","d":"The header checksum."},"answer":"d","explanation":"IPv6 removes the header checksum; the TTL is replaced by the Hop Limit.","status":"ok"},{"id":"062","unit":"03","topic":"IPv6 addresses","text":"The IPv6 address 2001:4600::0201:06FF:FEA5:3A4C is:","options":{"a":"A private address","b":"An address that a server can use to offer a service on the public IPv6 Internet","c":"An address that a host can use only to communicate with another host on the same link","d":"An address currently not valid in IPv6"},"answer":"b","explanation":"2000::/3 (prefix 001) is global unicast, so the address is valid and routable on the Internet; the interface ID is derived from the MAC through EUI-64.","status":"ok"},{"id":"063","unit":"03","topic":"IPv6 addresses","text":"IPv6 Site Local addresses:","options":{"a":"Are set automatically by the stations for on-link communications","b":"Are assigned by a central authority that guarantees their worldwide uniqueness","c":"Do not exist","d":"Are deprecated but can still be used"},"answer":"d","explanation":"Site-local addresses are deprecated in the slides.","status":"ok"},{"id":"064","unit":"03","topic":"IPv6 addresses","text":"Link-local addresses","options":{"a":"Are valid within an organization, which can use them to assign addresses to the machines in the various subnets of its intranet (they are the counterpart of IPv4 private addresses).","b":"Cannot be assigned to routers.","c":"Are normally built automatically by the station from the MAC address of its network card, prefixed with a predefined prefix.","d":"Are used to identify machines providing a given service (e.g. DNS servers)."},"answer":"c","explanation":"A link-local address can be generated automatically from the FE80 prefix and the interface ID.","status":"ok"},{"id":"065","unit":"03","topic":"IPv6 addresses","text":"Private IPv6 addresses","options":{"a":"Are defined so as to be unique with high probability, but cannot be used globally anyway","b":"Are used only for on-link communications","c":"Are used only on routers","d":"Are used to connect private networks through a public network"},"answer":"a","explanation":"Unique Local Addresses are for private use and are not routed on the global Internet.","status":"ok"},{"id":"066","unit":"03","topic":"Why IPv6","text":"one of the reasons that are favoring the spread of ipv6 is","options":{"a":"the lack of MAC addresses","b":"the possible inefficiency of the private ipv4 addressing","c":"the more and more widespread need to use multicast applications","d":"the low inclination of network operators to modify the configuration of their own networks"},"answer":"b","explanation":"The limits of IPv4 addressing, including the use of private addresses and NAT, favour IPv6.","status":"weak","duplicate_of":"069"},{"id":"067","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"At reboot, an IPv6 host will acquire the following address:","options":{"a":"The address cannot be known precisely, since the IPv6 address is regenerated each time with a random number in the part reserved for the Interface ID.","b":"A FE80::/32 address","c":"As for the link-local address, it will take the same IPv6 address it had before the reboot.","d":"The address depends entirely on the configuration it will acquire from its default router."},"answer":"c","explanation":"With a stable ID derived from the MAC the link-local address stays the same; with privacy extensions or another configuration it can change. The question does not specify the method.","status":"weak"},{"id":"068","unit":"03","topic":"Why IPv6","text":"One of the main strengths of the IPv6 protocol is","options":{"a":"The possibility to use 10Gb/s channels, a feature not available in IPv4","b":"The possibility to enable a routing mechanism based on names and no longer on addresses","c":"The large size of the addressing space","d":"The encryption of the packet payload, available by default for all the packets sent by a host"},"answer":"c","explanation":"The IPv6 address space grows to 128 bits.","status":"ok"},{"id":"069","unit":"03","topic":"Why IPv6","text":"One of the reasons that are favoring the spread of the IPv6 protocol is","options":{"a":"The more and more widespread need to use multicast applications","b":"The low inclination of network operators to modify the configuration of their own networks","c":"The possible inefficiency of the private IPv4 addressing","d":"The lack of MAC addresses"},"answer":"c","explanation":"Private IPv4 solutions are temporary remedies for the shortage of addresses.","status":"weak","duplicate_of":"066"},{"id":"070","unit":"03","topic":"Neighbor Discovery","text":"When an IPv6 host needs to learn the MAC address associated to a given IPv6 address","options":{"a":"It can send a specific ICMPv6 message in multicast over the network","b":"It can send a specific ICMPv6 message in unicast over the network","c":"It can send an ARP Request in broadcast over the network","d":"It can send a specific ICMPv6 message in broadcast over the network"},"answer":"a","explanation":"The host uses an ICMPv6 Neighbor Solicitation sent to the solicited-node multicast address.","status":"ok"},{"id":"071","unit":"03","topic":"IPv6 addresses","text":"The Interface ID of an IPv6 address","options":{"a":"Is the same for all devices within the same link","b":"Can be arbitrarily selected, sometimes it is derived from the MAC address of the interface","c":"Is assigned by the ISP according to a hierarchical schema","d":"Is assigned by the network administrator according to a hierarchical schema"},"answer":"b","explanation":"The interface ID can be chosen or generated, also starting from the MAC address.","status":"ok"},{"id":"072","unit":"03","topic":"IPv6 addresses","text":"What is the purpose of the \"scope\" associated with IPv6 addresses?","options":{"a":"It is used to resolve, in particular cases, the ambiguity about the sender.","b":"There is no scope associated with IPv6 addresses.","c":"It is needed to use global addresses.","d":"It is needed to use anycast addresses."},"answer":"a","explanation":"The scope of a multicast address indicates how far it propagates; no option says this.","status":"weak","no_correct_option":true},{"id":"073","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"The ICMPv6 Router Advertisement packet","options":{"a":"Is sent in reply to an ICMPv6 Neighbor Solicitation packet","b":"is a broadcast packet","c":"Allows devices to autoconfigure without using the DHCP protocol","d":"Is sent periodically by a router to all the other routers of the Internet"},"answer":"c","explanation":"The Router Advertisement announces the prefix usable for autoconfiguration without DHCPv6.","status":"ok"},{"id":"074","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"Does IPv6 stateless autoconfiguration have privacy issues?","options":{"a":"There are no particular issues.","b":"It does not allow encryption of the payload.","c":"The same interface can be identified if it connects to the Internet through various providers.","d":"It does not allow the use of security headers (such as IPsec)."},"answer":"c","explanation":"A stable interface ID derived from the MAC makes the same interface recognizable on different networks.","status":"ok"},{"id":"075","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"Stateless autoconfiguration in IPv6 requires:","options":{"a":"A DHCPv6 server (Dynamic Host Configuration Protocol version 6).","b":"A server on the local network.","c":"A server on the company network (intranet).","d":"It is possible even when no servers or routers are present."},"answer":"d","explanation":"The host can create a link-local address on its own; a router is needed to learn a global prefix.","status":"ok"},{"id":"076","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"In the IPv6 protocol:","options":{"a":"The routing protocols (e.g. the packet format) do not change compared with IPv4.","b":"The ARP protocol is incorporated into ICMPv6, but it keeps exactly the previous operating scheme (broadcast request, unicast reply).","c":"A station on a network segment can autoconfigure itself by listening to Router Advertisement messages.","d":"Like IPv4, IPv6 does not include router reconfiguration mechanisms."},"answer":"c","explanation":"The Router Advertisement lets the host build an address from the received prefix.","status":"ok"},{"id":"077","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"Using a privacy-aware autoconfiguration method (RFC-4941: privacy extensions for autoconfiguration), an IPv6 host contains an address:","options":{"a":"With both prefix and interface ID that are untraceable","b":"With an untraceable prefix","c":"Only valid within a VPN which guarantees user privacy","d":"With an untraceable interface ID"},"answer":"d","explanation":"Privacy extensions make the interface ID temporary and less traceable, not the prefix.","status":"ok"},{"id":"078","unit":"03","topic":"Transition and tunneling","text":"Which of these techniques is not a solution for the IPv4-IPv6 transition?","options":{"a":"6to4","b":"Teredo","c":"6over4","d":"6mix4"},"answer":"d","explanation":"6to4, Teredo and 6over4 appear in the slides; 6mix4 is not listed.","status":"ok"},{"id":"079","unit":"03","topic":"Transition and tunneling","text":"The GRE protocol is used to:","options":{"a":"Encapsulate packets in other IP headers, so that they can be sent over a tunnel.","b":"Guarantee the confidentiality of communications.","c":"Guarantee the authenticity of packets.","d":"Reserve bandwidth for the communication."},"answer":"a","explanation":"GRE encapsulates packets to carry them through a tunnel.","status":"ok"},{"id":"080","unit":"03","topic":"Transition and tunneling","text":"In a packet travelling on a GRE tunnel, how many headers can be present?","options":{"a":"Only one, otherwise addressing is ambiguous.","b":"Two headers, but the inner one can contain only private addresses.","c":"Two headers, without particular limitations.","d":"Two headers, but the outer one can contain only private addresses."},"answer":"c","explanation":"Tunneling can add an outer IP header to the inner one, without any requirement of private addresses.","status":"ok"},{"id":"081","unit":"03","topic":"Transition and tunneling","text":"The purpose of the GRE protocol is to:","options":{"a":"Protect packets against eavesdropping.","b":"Handle the encapsulation of packets to be carried through a tunnel.","c":"Authenticate the sender of the packets.","d":"Verify the integrity of incoming packets."},"answer":"b","explanation":"GRE handles encapsulation; it does not encrypt or authenticate automatically.","status":"ok"},{"id":"082","unit":"04","topic":"VLANs","text":"Increasing the number of VLANs:","options":{"a":"Collision domains increase","b":"Collision domains decrease","c":"Broadcast domains increase","d":"Broadcast domains decrease"},"answer":"c","explanation":"Each VLAN is a separate broadcast domain; increasing their number increases these domains.","status":"ok"},{"id":"083","unit":"04","topic":"VLANs","text":"A host belonging to a given VLAN","options":{"a":"Can contact only hosts in the same VLAN","b":"Can contact hosts in other VLANs through a router"},"answer":"b","explanation":"Between different VLANs, communication requires layer-3 routing.","status":"ok"},{"id":"084","unit":"04","topic":"VLANs","text":"Two hosts connected to an Ethernet switch","options":{"a":"Can communicate only if they belong to the same VLAN, whatever the network configuration","b":"Can communicate even if they belong to different VLANs, depending on the network configuration","c":"Must always be able to communicate without using an intermediate router","d":"Cannot communicate using a router, since they are connected to the same switch."},"answer":"b","explanation":"Two hosts in different VLANs can communicate if the network includes a router between the VLANs.","status":"ok"},{"id":"085","unit":"04","topic":"VLANs","text":"Two hosts connected to a switched Ethernet network through ports configured in Access mode:","options":{"a":"Cannot communicate","b":"If they belong to different VLANs, they can communicate only if connected to different switches and the link between the switches is configured in trunk mode","c":"can communicate only if they belong to the same VLAN","d":"If they belong to different VLANs, they may manage to communicate even if connected to different switches and the switch ports are configured in access mode"},"answer":"d","explanation":"VLANs configured on access ports of different switches are not propagated on the link: the local labels can differ and the hosts can still communicate.","status":"ok"},{"id":"086","unit":"04","topic":"Bridges and filtering database","text":"filtering table of a VLAN:","options":{"a":"Can be updated only manually","b":"Can be updated manually or automatically with dedicated protocols","c":"Contains only IPs of the local network"},"answer":"b","explanation":"The filtering database is learned automatically and can be administered; the reference to \"dedicated protocols\" is not very precise.","status":"ok"},{"id":"087","unit":"04","topic":"VLANs","text":"What is a consequence of using VLANs in a local network?","options":{"a":"Creating virtual interfaces on the switches which, being virtual, are always working","b":"Broadcast traffic is limited to the VLAN where it was generated","c":"The security of communication on the corporate network increases, since frames are encrypted.","d":"Users are forced to authenticate before they can access the VLAN"},"answer":"b","explanation":"Broadcast stays in the domain of the VLAN that generated it.","status":"ok"},{"id":"088","unit":"04","topic":"Bridges and filtering database","text":"The entries of the filtering database of an Ethernet switch","options":{"a":"All have infinite validity","b":"Have a validity time generally settable by the switch administrator","c":"All have a validity time below one second, to best handle the movements of devices","d":"Have a validity time that varies over time, according to the number of frames received"},"answer":"b","explanation":"Learned entries have an aging timer, which is generally configurable.","status":"ok"},{"id":"089","unit":"04","topic":"VLANs","text":"Given a LAN on which some VLANs have been defined, a broadcast frame:","options":{"a":"Possibly reaches only a portion of the LAN","b":"Reaches all the hosts of the LAN"},"answer":"a","explanation":"The broadcast frame reaches only the portion of the LAN that belongs to the VLAN.","status":"ok"},{"id":"090","unit":"04","topic":"Collision and broadcast domains","text":"For what reason can two Ethernet frames collide?","options":{"a":"Switched full duplex","b":"Switched half duplex","c":"Because of the queue in the switch buffers","d":"It often happens because of channel contention"},"answer":"b","explanation":"A half-duplex link keeps a collision domain; in full duplex the switch avoids collisions on the link.","status":"weak"},{"id":"091","unit":"04","topic":"Bridges and filtering database","text":"A switch receives a frame whose destination MAC is not in the filtering database. What does it do?","options":{"a":"It floods it on all ports except the one it arrived on.","b":"It sends an ARP request in broadcast to find out on which port the host is.","c":"It sends it only on the port towards the default gateway.","d":"It drops it, because the destination is unknown."},"answer":"a","explanation":"A transparent bridge floods frames towards unknown destinations; the reply will then let it learn where the host is.","status":"ok"},{"id":"092","unit":"04","topic":"Bridges and filtering database","text":"How does a switch populate its filtering database (backward learning)?","options":{"a":"It associates the destination MAC of forwarded frames with the output port.","b":"It associates the source MAC of received frames with the port they arrive from.","c":"It periodically exchanges its tables with the neighbouring switches.","d":"It sends periodic broadcast requests to all the hosts."},"answer":"b","explanation":"Backward learning looks at the source MAC: if a frame from H1 arrives from port 3, H1 is reachable through port 3.","status":"ok"},{"id":"093","unit":"04","topic":"Spanning tree and loops","text":"What is the purpose of the Spanning Tree Protocol in a switched LAN?","options":{"a":"Balancing the traffic over all the redundant links.","b":"Computing the least-cost path to each host, like a routing protocol.","c":"Separating the traffic of different VLANs on the same link.","d":"Logically disabling some links to remove loops, keeping redundancy."},"answer":"d","explanation":"Layer-2 loops cause broadcast storms and filtering database instability; STP disables some links, which become active again in case of failure.","status":"ok"},{"id":"094","unit":"04","topic":"802.1Q, access and trunk ports","text":"What does IEEE 802.1Q tagging add to an Ethernet frame?","options":{"a":"A new source MAC address that identifies the VLAN.","b":"An outer IP header containing the VLAN ID.","c":"4 bytes in the MAC header, including the VLAN ID.","d":"2 bytes at the end of the frame, after the FCS field."},"answer":"c","explanation":"The 802.1Q tag (Ethertype 0x8100 + priority + VLAN ID) adds 4 bytes to the MAC header; the frame becomes 4 bytes longer.","status":"ok"},{"id":"095","unit":"04","topic":"802.1Q, access and trunk ports","text":"Which Ethertype value indicates a frame with an 802.1Q tag?","options":{"a":"0x8100","b":"0x0806","c":"0x86DD","d":"0x0800"},"answer":"a","explanation":"0x8100 signals the VLAN tag; 0x0800 is IPv4, 0x86DD is IPv6, 0x0806 is ARP.","status":"ok"},{"id":"096","unit":"04","topic":"802.1Q, access and trunk ports","text":"How does a switch port configured in access mode behave?","options":{"a":"It removes the tag from broadcast frames and leaves the others tagged.","b":"It accepts frames of any VLAN and forwards them unchanged.","c":"It sends and receives tagged frames, even of several different VLANs.","d":"It uses only untagged frames, associated with the port's VLAN."},"answer":"d","explanation":"Access ports use standard Ethernet frames: the host knows nothing about the VLAN, which is decided by the port configuration.","status":"ok"},{"id":"097","unit":"04","topic":"802.1Q, access and trunk ports","text":"When is a port in trunk mode needed?","options":{"a":"On every switch port to which a host belonging to some VLAN is connected.","b":"On a link carrying several VLANs, e.g. switch to switch or to a router.","c":"When the connected switches are VLAN-unaware.","d":"Between two switches that belong to a single VLAN."},"answer":"b","explanation":"Tagging is needed only where several VLANs pass on the same link (switch-switch, server, router); trunk ports must be configured explicitly.","status":"ok"},{"id":"098","unit":"04","topic":"VLANs","text":"Can a broadcast storm in the red VLAN harm the green VLAN?","options":{"a":"No: spanning tree automatically blocks the VLAN involved.","b":"Yes: broadcasts are propagated to all the VLANs of the switch.","c":"Yes: broadcasts stay in the red one, but a shared trunk can saturate.","d":"No: VLANs guarantee complete isolation, even of shared trunk links."},"answer":"c","explanation":"VLANs separate broadcast domains but share links: a congested trunk can no longer carry the traffic of the other VLANs.","status":"ok"},{"id":"099","unit":"04","topic":"VLANs","text":"Two hosts belong to different VLANs. What must their IP addresses be like?","options":{"a":"In the same IP network, provided the link between the switches is a trunk.","b":"In the same IP network, provided there is a router between the VLANs.","c":"In different IP networks, because ARP does not leave the VLAN.","d":"Anything: the 802.1Q tag is enough to tell the hosts apart."},"answer":"c","explanation":"Broadcast (and therefore ARP) does not leave the VLAN: hosts in different VLANs must be in different IP networks and communicate through a router.","status":"ok"},{"id":"100","unit":"04","topic":"Spanning tree and loops","text":"How are VLANs and Spanning Tree combined according to the slides?","options":{"a":"The spanning tree is computed only on trunk links.","b":"They are independent in theory, but almost all vendors offer a per-VLAN STP.","c":"All the VLANs must use the same root bridge.","d":"VLANs make spanning tree useless, because they separate the broadcast domains."},"answer":"b","explanation":"In theory a single tree is computed and VLANs are then used on top of it; in practice there is the Per-VLAN Spanning Tree (in Cisco it is the only option).","status":"ok"},{"id":"101","unit":"04","topic":"VLANs","text":"In which case is a VLAN-unaware switch acceptable in a corporate network with VLANs?","options":{"a":"Connected to a trunk port, because it ignores the VLAN ID field.","b":"Always, because it correctly forwards tagged frames of any VLAN.","c":"As a backbone switch between two VLAN-aware devices, provided the link is a trunk.","d":"Only on the access side, with all the clients in the same VLAN."},"answer":"d","explanation":"VLAN-unaware switches do not accept tagged frames (they can drop them as too long), but they are fine on the access side if they serve a single VLAN.","status":"ok"},{"id":"102","unit":"04","topic":"Collision and broadcast domains","text":"Which device separates collision domains but not broadcast domains?","options":{"a":"Switch.","b":"Hub.","c":"Router.","d":"Repeater."},"answer":"a","explanation":"Repeaters and hubs (L1) extend the same collision domain; switches and bridges (L2) separate collision domains but stay in the same broadcast domain; routers (L3) also separate broadcast domains.","status":"ok"},{"id":"103","unit":"01","topic":"IPv4 multicast and IGMP","text":"multicast communications in an IPv4 network","options":{"a":"are possible only within a single LAN, even with the use of additional protocols","b":"are always possible, IGMP only makes them more efficient","c":"are not possible without the use of additional protocols in the network","d":"are possible on a geographical scale thanks to the IGMP protocol alone"},"answer":"c","explanation":"IPv4 multicast beyond the LAN requires additional group-management and multicast routing mechanisms.","status":"weak"},{"id":"104","unit":"01","topic":"IPv4 multicast and IGMP","text":"The implementation of multicast in IPv4 is:","options":{"a":"Available without the need for additional protocols","b":"Available but with additional protocols","c":"Not supported"},"answer":"b","explanation":"IPv4 supports multicast, but group management and forwarding across several networks require additional protocols.","status":"ok"},{"id":"105","unit":"01","topic":"IPv4 multicast and IGMP","text":"In an IPv4 network:","options":{"a":"A station receives a multicast packet for a given group only if it has joined that group, whatever layer-2 technology is used.","b":"A station may receive a multicast packet for a given group even if it has not joined that group.","c":"a station always delivers all the received multicast packets to the application layer.","d":"a station is not able to understand an IPv4 multicast packet."},"answer":"b","explanation":"The mapping between IP multicast addresses and MAC addresses is not one-to-one; a station can receive frames for groups it has not joined.","status":"ok"},{"id":"106","unit":"01","topic":"IPv4 multicast and IGMP","text":"multicast groups in IPv4 are","options":{"a":"identified by special IP addresses that cannot be assigned to individual stations","b":"identified by the list of the MAC addresses of the stations belonging to a given group. These addresses are then used as destination MAC addresses in the multicast frames sent","c":"nonexistent","d":"identified by the list of the IP addresses of the stations belonging to a given group. These addresses are then used as destination IP addresses in the multicast frames sent to those stations"},"answer":"a","explanation":"A multicast group is identified by a group IP address, not by the list of its members.","status":"ok"},{"id":"107","unit":"01","topic":"IPv4 multicast and IGMP","text":"The IGMP protocol","options":{"a":"Allows an IPv4 router to discover which multicast groups are present on a directly connected network","b":"Allows an IPv4 host to create a new multicast group","c":"Allows an IPv4 router to discover which multicast groups are active at a given moment in the whole Internet","d":"Is a new version of the ICMP protocol"},"answer":"a","explanation":"IGMP lets the router know which groups are present on the directly connected link.","status":"ok"},{"id":"108","unit":"01","topic":"IPv4 multicast and IGMP","text":"The IGMP protocol","options":{"a":"Allows a host to communicate to other hosts belonging to a given multicast group its own interest in entering the group","b":"Allows a router to communicate to other routers in the Internet network its own interest in receiving the traffic related to a given multicast group","c":"Carries the multicast traffic generated by hosts","d":"Allows a host to communicate to routers in the network its own interest in receiving the traffic related to a given multicast group"},"answer":"d","explanation":"Through IGMP the host tells the local routers that it wants to receive a group.","status":"ok"},{"id":"109","unit":"05","topic":"Delay and jitter","text":"The main contribution to the latency experienced in the nodes of a heavily loaded packet network is given by","options":{"a":"The time needed to process the packet.","b":"The time taken to transmit the packet on an output link (transmission delay).","c":"The time taken to locate, in the routing table or in the forwarding table, the information need to forward the packet.","d":"The time spent in buffers while waiting for resources occupied by other packets to become available (for example, the transmission capacity of a link)."},"answer":"d","explanation":"Under heavy load, the wait in the queue before the output resource becomes free dominates.","status":"ok"},{"id":"110","unit":"05","topic":"Token bucket, policing and shaping","text":"With the token bucket mechanism it is possible to control:","options":{"a":"The maximum crossing time of a router.","b":"The internal management of the queues with WFQ.","c":"The minimum data injection rate.","d":"The maximum burst size and the average data injection rate."},"answer":"d","explanation":"The token bucket limits the maximum burst through its capacity and the average rate through the generation of tokens.","status":"ok"},{"id":"111","unit":"05","topic":"Token bucket, policing and shaping","text":"What are policing mechanisms used for?","options":{"a":"They are used by the user to agree with the provider on the QoS level to obtain.","b":"They are used by the service provider to check that the traffic injected by the customer complies with the agreements.","c":"They are used by the user to check that the traffic coming from the provider complies with the agreements.","d":"They are used in the various routers to guarantee a maximum crossing time for each of them."},"answer":"b","explanation":"Policing at the edge checks that the user's traffic respects the agreed profile.","status":"ok"},{"id":"112","unit":"05","topic":"IntServ and DiffServ","text":"DiffServ differs from IntServ because:","options":{"a":"DiffServ tends to provide a QoS guarantee that IntServ does not give.","b":"DiffServ introduces new protocols to allow resource reservation in order to obtain a given QoS.","c":"IntServ tends to provide a QoS guarantee that DiffServ does not give.","d":"DiffServ tends to guarantee a maximum crossing time, while IntServ tends to provide a guaranteed minimum bandwidth."},"answer":"c","explanation":"IntServ handles per-flow reservations with guarantees; DiffServ applies per-class treatments.","status":"ok"},{"id":"113","unit":"05","topic":"Token bucket, policing and shaping","text":"In the token bucket algorithm:","options":{"a":"The bucket capacity is related to the long-term average rate.","b":"The bucket capacity is related to the maximum burst size.","c":"The bucket capacity is directly related to the bandwidth.","d":"It is used to implement weighted fair queuing."},"answer":"b","explanation":"The bucket capacity determines how many tokens can accumulate, and therefore the maximum burst.","status":"ok"},{"id":"114","unit":"05","topic":"IntServ and DiffServ","text":"The RSVP protocol (Resource reSerVation Protocol) is able to:","options":{"a":"Limit the delay variations (jitter) experienced by packets in routers","b":"Let routers know the quality of service requests made by applications","c":"Reserve computing resources in servers that share their processors","d":"Check the delays and losses experienced on the network by the packets of multimedia applications."},"answer":"b","explanation":"RSVP signals to the routers the resource and QoS requests of the applications.","status":"ok"},{"id":"115","unit":"05","topic":"Scheduling","text":"Scheduling algorithms are used:","options":{"a":"In access routers, to make sure that the traffic generated by a user complies with the traffic profile contracted with its service provider.","b":"In firewalls, to delay packets entering a corporate network from the Internet in order to prevent some types of security attacks.","c":"In routers, to decide the order in which the packets waiting at an interface must be transmitted.","d":"In routers, to properly schedule the list of configuration commands issued by the user so as to minimize the disruption caused by the time needed to apply the changes."},"answer":"c","explanation":"Scheduling chooses the transmission order of the packets queued at the interface.","status":"ok"},{"id":"116","unit":"05","topic":"IntServ and DiffServ","text":"The DiffServ architecture is characterized by:","options":{"a":"A mechanism to separate traffic into classes, each of which can receive a specific service in every node it crosses","b":"Sophisticated signalling protocols for resource reservation","c":"The ability to provide guaranteed-quality service to the applications or flows that explicitly request it from the network","d":"Sophisticated routing protocols to choose the path of every single packet so as to ensure that it receives the service it needs"},"answer":"a","explanation":"DiffServ classifies and marks traffic to apply a per-class treatment in the nodes.","status":"ok"},{"id":"117","unit":"05","topic":"IntServ and DiffServ","text":"In DiffServ, a \"Class of Service\" identifies:","options":{"a":"A set of packets belonging to the same VoIP session","b":"A set of packets that receive the same treatment by the router (for example, all VoIP traffic)","c":"An operating mode of the edge routers, which must classify and mark incoming packets"},"answer":"b","explanation":"A class groups packets that receive the same forwarding treatment.","status":"ok"},{"id":"118","unit":"05","topic":"Scheduling","text":"Quality of service can be guaranteed on packet networks when","options":{"a":"Packets are carried by a cell-switching infrastructure (for example ATM)","b":"Network nodes implement suitable mechanisms that regulate the service of packets (for example scheduling algorithms)","c":"Applications are able to encode the information to be transferred into layers of different importance"},"answer":"b","explanation":"Guarantees require network mechanisms to classify, control and schedule packets.","status":"ok"},{"id":"119","unit":"05","topic":"IntServ and DiffServ","text":"The Integrated Services (IntServ) solution has been standardized to","options":{"a":"Allow applications to request to and receive from the network the quality of service they need.","b":"Mark packets as belonging to a specific class of service so that they can receive the most suitable service.","c":"Integrate within the network traditional IP routers and MPLS (Multi-Protocol Label Switching) Label Switch Routers (LSRs), thanks to the common deployment of RSVP (Resource ReSerVation Protocol).","d":"Enable the integrated deployment of IP routers and Ethernet switches to guarantee network connectivity."},"answer":"a","explanation":"IntServ lets applications ask the network for the level of service they need.","status":"ok"},{"id":"120","unit":"06","topic":"Definition and capacity planning","text":"According to the definition of cloud computing given in the slides, which element describes the access to resources?","options":{"a":"Access to configurable resources, activated after the provider's manual approval.","b":"Ubiquitous, on-demand network access to a shared pool of configurable resources.","c":"On-demand access to a shared pool, but only from the provider's internal network.","d":"Ubiquitous network access to dedicated resources, pre-assigned to each consumer."},"answer":"b","explanation":"Cloud access is network-based, ubiquitous and on demand; the resources belong to a reconfigurable pool.","status":"ok"},{"id":"121","unit":"06","topic":"Definition and capacity planning","text":"A service keeps servers sized for the annual peak, but almost always unused. Which capacity planning problem does it illustrate?","options":{"a":"Under-provisioning: the capacity is not enough at peak times.","b":"Elasticity: the capacity is adapted automatically to the load.","c":"Over-provisioning: you pay for capacity that remains unused.","d":"Lag strategy: capacity is added only after saturation."},"answer":"c","explanation":"Capacity bought for the peak but almost always unused leads to over-provisioning and unnecessary costs.","status":"ok"},{"id":"122","unit":"06","topic":"Definition and capacity planning","text":"If the available capacity cannot meet the users' demand, which consequence is given in the slides?","options":{"a":"Automatic switch to a lead strategy by the provider.","b":"Over-provisioning, with fixed costs higher than necessary.","c":"Increase of the operational overhead due to unused capacity.","d":"Possible loss of business due to degraded quality of service."},"answer":"d","explanation":"If the resources are not enough, the service degrades and can lose users or requests.","status":"ok"},{"id":"123","unit":"06","topic":"Definition and capacity planning","text":"A company adds capacity before the expected demand requires it. Which capacity planning strategy is it applying?","options":{"a":"Lead strategy.","b":"Lag strategy.","c":"Early vertical scaling.","d":"Match strategy."},"answer":"a","explanation":"The lead strategy anticipates the expected growth, adding capacity before the load arrives.","status":"ok"},{"id":"124","unit":"06","topic":"Definition and capacity planning","text":"The so-called lag strategy adds capacity:","options":{"a":"when the resource reaches full capacity.","b":"ahead of the expected growth in demand.","c":"at regular intervals, regardless of the load.","d":"in small increments as demand grows."},"answer":"a","explanation":"The lag strategy waits until the existing capacity is saturated before expanding it.","status":"ok"},{"id":"125","unit":"06","topic":"Definition and capacity planning","text":"Which behaviour represents a match strategy?","options":{"a":"Adding capacity in advance, before demand grows.","b":"Adding capacity in small steps as demand grows.","c":"Keeping capacity fixed and rejecting excess requests.","d":"Adding capacity only when the resources are already saturated."},"answer":"b","explanation":"The match strategy follows demand with small, repeated increments.","status":"ok"},{"id":"126","unit":"06","topic":"Definition and capacity planning","text":"Which item is an example of operational overhead for an IT infrastructure?","options":{"a":"Software licences bought once at the start of the project.","b":"Initial purchase of servers, storage and network devices.","c":"Technical staff, upgrades, power and cooling.","d":"Construction of the premises that will host the data center."},"answer":"c","explanation":"These are ongoing operating costs; the purchase of hardware, initial licences and premises are up-front costs.","status":"ok"},{"id":"127","unit":"06","topic":"Scaling","text":"Replacing a machine with another of the same type but with greater capacity is an example of:","options":{"a":"Scaling in (horizontal).","b":"Scaling out (horizontal).","c":"Scaling down (vertical).","d":"Scaling up (vertical)."},"answer":"d","explanation":"Increasing the power of the same instance is vertical scaling, called scaling up.","status":"ok"},{"id":"128","unit":"06","topic":"Scaling","text":"An application adds three instances of the same type to absorb a load increase. Which form of scaling was applied?","options":{"a":"Scaling up (vertical).","b":"Scaling out (horizontal).","c":"Scaling in (horizontal).","d":"Scaling down (vertical)."},"answer":"b","explanation":"Adding parallel instances is horizontal scaling, called scaling out.","status":"ok"},{"id":"129","unit":"06","topic":"Roles and SLA","text":"In the terminology of the slides, a cloud service is:","options":{"a":"an IT resource made remotely accessible through the cloud.","b":"a contract that sets the service levels between provider and consumer.","c":"a public web application offered for free on the Internet.","d":"a virtual machine rented by the hour from an IaaS provider."},"answer":"a","explanation":"A cloud service exposes an IT resource that can be used remotely through the cloud environment.","status":"ok"},{"id":"130","unit":"06","topic":"Roles and SLA","text":"Which party makes cloud resources available and takes care of the overall operation of the infrastructure?","options":{"a":"Cloud resource administrator.","b":"Cloud broker.","c":"Cloud provider.","d":"Cloud carrier."},"answer":"c","explanation":"The provider makes available and manages the infrastructure that delivers the service.","status":"ok"},{"id":"131","unit":"06","topic":"Roles and SLA","text":"An organization signs an agreement to use IT resources offered by a cloud provider. Which role does it take?","options":{"a":"Cloud resource administrator.","b":"Cloud provider.","c":"Cloud broker.","d":"Cloud consumer."},"answer":"d","explanation":"The consumer is whoever uses the offered resources and subscribes to their terms.","status":"ok"},{"id":"132","unit":"06","topic":"Roles and SLA","text":"What does an SLA between cloud provider and cloud consumer mainly specify?","options":{"a":"The price of each resource and the pay-per-use billing method.","b":"The procedures and deadlines by which the cloud auditor periodically certifies the provider's security.","c":"The physical resources that the provider dedicates exclusively to the consumer.","d":"The service guarantees (e.g. availability, performance) and the obligations of the parties."},"answer":"d","explanation":"The SLA defines the service levels and obligations agreed between provider and customer.","status":"ok"},{"id":"133","unit":"06","topic":"Roles and SLA","text":"An intermediary negotiates and manages the use of services between cloud provider and cloud consumer. It is a:","options":{"a":"cloud carrier.","b":"cloud auditor.","c":"cloud broker.","d":"cloud provider."},"answer":"c","explanation":"The broker mediates the acquisition and management of services between provider and consumer.","status":"ok"},{"id":"134","unit":"06","topic":"Roles and SLA","text":"Who performs independent assessments of the security, privacy and performance of a cloud environment?","options":{"a":"The cloud broker.","b":"The cloud auditor.","c":"The cloud carrier.","d":"The cloud provider."},"answer":"b","explanation":"The auditor independently checks aspects such as security, privacy and performance.","status":"ok"},{"id":"135","unit":"06","topic":"Roles and SLA","text":"Which role provides network connectivity between cloud consumer and cloud provider?","options":{"a":"Cloud carrier.","b":"Cloud broker.","c":"Cloud auditor.","d":"Cloud provider."},"answer":"a","explanation":"The carrier ensures the network connection between whoever uses and whoever provides the cloud.","status":"ok"},{"id":"136","unit":"06","topic":"Cloud characteristics","text":"In the on-demand self-service model, the consumer:","options":{"a":"pays for resources based on the actually measured usage.","b":"activates resources on its own, with no human action by the provider.","c":"accesses the service from any device connected to the network.","d":"can use new resources only after a request approved by the provider."},"answer":"b","explanation":"On-demand self-service = autonomous activation; the other options describe measured usage and ubiquitous access.","status":"ok"},{"id":"137","unit":"06","topic":"Cloud characteristics","text":"The ubiquitous access characteristic mainly concerns:","options":{"a":"the ability to keep working if a site fails.","b":"the sharing of the same physical resources among several consumers, kept isolated.","c":"the possibility of activating resources without human intervention by the provider.","d":"network access to the service from different devices and interfaces."},"answer":"d","explanation":"Ubiquitous access makes the service available over the network through different interfaces and devices.","status":"ok"},{"id":"138","unit":"06","topic":"Cloud characteristics","text":"What does multitenancy describe in the slides?","options":{"a":"The replication of a service over several sites to guarantee its continuity.","b":"The assignment of a dedicated instance of the service to each consumer.","c":"A shared instance that serves several consumers isolated from each other.","d":"The simultaneous use of several providers by the same consumer."},"answer":"c","explanation":"Multitenancy shares a platform among tenants, keeping their data and activities separate.","status":"ok"},{"id":"139","unit":"06","topic":"Cloud characteristics","text":"A cloud automatically increases and reduces resources in response to the load at runtime. This property is:","options":{"a":"elasticity.","b":"on-demand self-service.","c":"resiliency.","d":"measured usage."},"answer":"a","explanation":"Elasticity increases or decreases the resources as the load varies during operation.","status":"ok"},{"id":"140","unit":"06","topic":"Cloud characteristics","text":"Which platform capability enables charging based on the resources actually used or on the access time?","options":{"a":"Elasticity.","b":"On-demand self-service.","c":"Measured usage.","d":"Multitenancy (resource pooling)."},"answer":"c","explanation":"Usage measurement records consumption and duration, making pay-per-use charging possible.","status":"ok"},{"id":"141","unit":"06","topic":"Cloud characteristics","text":"A redundant resource at another site automatically takes over when the active one fails. The example illustrates:","options":{"a":"multitenancy.","b":"elasticity.","c":"scaling out.","d":"resiliency."},"answer":"d","explanation":"Resiliency uses redundancy and failover to keep the service running after a failure.","status":"ok"},{"id":"142","unit":"06","topic":"Deployment models","text":"Which description corresponds to a public cloud?","options":{"a":"Environment shared by several organizations with common needs, with limited access.","b":"Publicly accessible environment, owned and managed by a third-party provider.","c":"Environment made of two or more different deployment models.","d":"Environment owned by a single organization and offered to its departments."},"answer":"b","explanation":"The public cloud is offered to a wide public by an external provider.","status":"ok"},{"id":"143","unit":"06","topic":"Deployment models","text":"In a private cloud internal to the company, how can the roles be distributed?","options":{"a":"An IT department acts as provider, while other departments are consumers.","b":"Each department must manage its own separate private cloud.","c":"The organization acts as consumer and the provider is an external party.","d":"The provider and consumer roles do not exist, since there is a single party."},"answer":"a","explanation":"In a private cloud the organization can play the provider and consumer roles internally.","status":"ok"},{"id":"144","unit":"06","topic":"Deployment models","text":"Several independent organizations share cloud resources, but access remains limited to the members of the group. Which model is it?","options":{"a":"Public cloud.","b":"Hybrid cloud.","c":"Private cloud.","d":"Community cloud."},"answer":"d","explanation":"The community cloud is shared by several organizations, with access restricted to the community.","status":"ok"},{"id":"145","unit":"06","topic":"Deployment models","text":"A company uses a private cloud for sensitive data and a public one for other services. The overall deployment is:","options":{"a":"a private cloud.","b":"a multi-tenant public cloud.","c":"a hybrid cloud.","d":"a community cloud."},"answer":"c","explanation":"The hybrid cloud integrates distinct environments, here a private one and a public one.","status":"ok"},{"id":"146","unit":"06","topic":"Service models (IaaS, PaaS, SaaS)","text":"A customer creates VMs, attaches virtual disks, configures networks and installs its own operating system. Which delivery model corresponds?","options":{"a":"Private cloud.","b":"IaaS.","c":"SaaS.","d":"PaaS."},"answer":"b","explanation":"IaaS exposes compute, storage and network; the customer installs and manages its own operating system.","status":"ok"},{"id":"147","unit":"06","topic":"Service models (IaaS, PaaS, SaaS)","text":"In which model does the provider offer a ready platform on which the customer develops and deploys applications, hiding the details of the infrastructure?","options":{"a":"PaaS.","b":"IaaS.","c":"Hybrid cloud.","d":"SaaS."},"answer":"a","explanation":"PaaS provides an application platform, leaving the management of the underlying infrastructure to the provider.","status":"ok"},{"id":"148","unit":"06","topic":"Service models (IaaS, PaaS, SaaS)","text":"A shared program is offered as a product usable by many consumers, without each of them managing the underlying platform. It is an example of:","options":{"a":"SaaS.","b":"Community cloud.","c":"IaaS.","d":"PaaS."},"answer":"a","explanation":"SaaS delivers the application ready to use, without the customer managing the platform directly.","status":"ok"},{"id":"149","unit":"06","topic":"Service models (IaaS, PaaS, SaaS)","text":"Comparing the cloud service models, which statement about the consumer's control is consistent with the slides?","options":{"a":"Between IaaS and SaaS control is equivalent: only who pays changes.","b":"In PaaS the consumer has full administrative control over the infrastructure.","c":"In SaaS the consumer has more control, because it manages the application.","d":"In IaaS the consumer has more control over the resources than in SaaS."},"answer":"d","explanation":"In IaaS the customer configures more layers of the stack than in SaaS, where it only uses the application.","status":"ok"},{"id":"150","unit":"07","topic":"VMs, hypervisors and VMM","text":"Which characteristic distinguishes a system virtual machine in the model presented?","options":{"a":"It requires the physical hardware to be dedicated to that single VM.","b":"It runs its own operating system on virtualized hardware.","c":"It virtualizes a single process, as the Java Virtual Machine does.","d":"It runs its processes directly on the kernel of the host system."},"answer":"b","explanation":"The VM presents virtual hardware on which a separate guest operating system runs.","status":"ok"},{"id":"151","unit":"07","topic":"VMs, hypervisors and VMM","text":"Which set of elements typically represents a VM in the slides?","options":{"a":"A host process isolated with namespaces and cgroups.","b":"Read-only image layers plus a writable layer.","c":"Configuration files, virtual disks and possibly snapshots.","d":"A physical disk partition with the host operating system."},"answer":"c","explanation":"Configuration, disks and snapshots represent the state and structure of the VM.","status":"ok"},{"id":"152","unit":"07","topic":"VMs, hypervisors and VMM","text":"Why can several VMs on one server improve resource utilization?","options":{"a":"They remove the operating system overhead of each workload.","b":"They consolidate workloads that used to run on separate servers.","c":"They let each application use several dedicated physical CPUs.","d":"They reserve all the physical memory of the server for each VM."},"answer":"b","explanation":"Consolidating several workloads on the same host exploits physical capacity that was previously underused.","status":"ok"},{"id":"153","unit":"07","topic":"VMs, hypervisors and VMM","text":"What advantage comes from representing a VM as a set of files?","options":{"a":"It is easier to copy, save or move it between compatible hosts.","b":"It can run without a hypervisor on the destination host.","c":"Performance improves because the virtual disk stays in RAM.","d":"The guest shares the host kernel and boots faster."},"answer":"a","explanation":"A VM described by files can be copied or transferred to a compatible host.","status":"ok"},{"id":"154","unit":"07","topic":"VMs, hypervisors and VMM","text":"In virtualization terminology, what is the guest operating system?","options":{"a":"The operating system on which a type 2 hypervisor is installed.","b":"The minimal core of a microkernelized hypervisor.","c":"The operating system installed and run inside a VM.","d":"The operating system of the Hyper-V parent partition."},"answer":"c","explanation":"The guest is the operating system run inside the virtual machine.","status":"ok"},{"id":"155","unit":"07","topic":"VMs, hypervisors and VMM","text":"What role does the virtual machine monitor (VMM) play?","options":{"a":"It translates the guest's system calls for the shared host kernel.","b":"It assigns each VM an exclusive physical core and disk.","c":"It manages the life cycle of containers on several nodes.","d":"It abstracts the hardware for the VMs and controls access to it."},"answer":"d","explanation":"The VMM mediates the guest's access to the virtualized hardware resources.","status":"ok"},{"id":"156","unit":"07","topic":"VMs, hypervisors and VMM","text":"Which property is required of the hypervisor to keep the VMs separate?","options":{"a":"Executing the guest's privileged instructions without checks.","b":"Assigning the same physical memory space to all the VMs.","c":"Isolating the access to the resources assigned to each VM.","d":"Sharing the host kernel among the VMs to reduce the overhead."},"answer":"c","explanation":"The hypervisor must prevent a VM from improperly accessing the resources of another one.","status":"ok"},{"id":"157","unit":"07","topic":"VMs, hypervisors and VMM","text":"What does the live migration of a VM indicate?","options":{"a":"Creating an identical copy of the VM on another host.","b":"Copying a VM to another host after shutting it down.","c":"Periodically saving the state of the VM in a snapshot.","d":"Moving a VM between hosts while keeping the service running."},"answer":"d","explanation":"Live migration moves the running VM; shutting it down and copying it is a cold migration, an identical copy is a clone.","status":"ok"},{"id":"158","unit":"07","topic":"Type 1 and type 2 hypervisors","text":"Where is a type 1 hypervisor located?","options":{"a":"In the shared kernel used by containers.","b":"Directly on the physical hardware (bare metal).","c":"As an application on top of a host operating system.","d":"Inside a guest operating system."},"answer":"b","explanation":"A type 1 hypervisor runs directly on the hardware, below the guests.","status":"ok"},{"id":"159","unit":"07","topic":"Type 1 and type 2 hypervisors","text":"Which advantage is associated in the slides with a type 1 hypervisor?","options":{"a":"Lower overhead than a hosted hypervisor.","b":"No need for drivers for the physical hardware.","c":"Ability to run guests without an operating system.","d":"Easier installation on a desktop PC."},"answer":"a","explanation":"Avoiding the passage through a host system removes part of the overhead.","status":"ok"},{"id":"160","unit":"07","topic":"Type 1 and type 2 hypervisors","text":"In a microkernelized type 1 hypervisor, where are various management services moved?","options":{"a":"Into components outside the core, such as the management partition.","b":"Into the guest operating systems, modified to use hypercalls.","c":"Into the host operating system on which the hypervisor is installed.","d":"Into the hypervisor core, together with the device drivers."},"answer":"a","explanation":"In the microkernelized design (e.g. Hyper-V) the core is thin and drivers/services are in the parent partition; in the monolithic one (e.g. ESX) the drivers are in the core.","status":"ok"},{"id":"161","unit":"07","topic":"Type 1 and type 2 hypervisors","text":"How is a type 2 hypervisor installed?","options":{"a":"Directly on the physical hardware.","b":"As an application on a host operating system.","c":"In the motherboard firmware.","d":"As a module loaded inside a type 1 hypervisor."},"answer":"b","explanation":"The type 2 hypervisor is hosted by a pre-existing operating system.","status":"ok"},{"id":"162","unit":"07","topic":"Type 1 and type 2 hypervisors","text":"Why can a type 2 hypervisor introduce more overhead?","options":{"a":"It cannot exploit the virtualization extensions of the CPU.","b":"Every guest instruction must always be emulated in software.","c":"The guest system must be modified to use hypercalls.","d":"The requests of the VM also go through the host operating system."},"answer":"d","explanation":"The guest's operations also pass through the host system and can take more time.","status":"ok"},{"id":"163","unit":"07","topic":"VMs, hypervisors and VMM","text":"What does the virtual hardware profile of a VM describe?","options":{"a":"The list of processes running in the guest system.","b":"The physical resources of the host that remain reserved for the hypervisor and management.","c":"The virtual resources (CPU, RAM, devices) exposed to the guest.","d":"The state of the VM saved at a precise instant."},"answer":"c","explanation":"The virtual hardware profile specifies the CPU, memory and peripherals seen by the guest.","status":"ok"},{"id":"164","unit":"07","topic":"Virtualization techniques","text":"In full virtualization, which assumption holds for the guest system?","options":{"a":"It can run only on CPUs with virtualization extensions.","b":"It must be modified to invoke the hypervisor through hypercalls.","c":"It must share the kernel with the host operating system.","d":"It runs unmodified; the VMM handles the sensitive operations."},"answer":"d","explanation":"Full virtualization lets the unmodified guest run thanks to the intervention of the VMM.","status":"ok"},{"id":"165","unit":"07","topic":"Virtualization techniques","text":"In full virtualization (without hardware support), how are the privileged instructions that the guest cannot execute directly handled?","options":{"a":"They are intercepted or translated by the VMM.","b":"They are ignored, because the guest runs in user mode.","c":"They are replaced in the guest's code by explicit hypercalls.","d":"They are executed directly on the physical CPU without checks."},"answer":"a","explanation":"In software virtualization the VMM intercepts (trap-and-emulate) or translates (binary translation) the sensitive instructions; hypercalls are typical of paravirtualization.","status":"ok"},{"id":"166","unit":"07","topic":"Virtualization techniques","text":"Which modification characterizes paravirtualization?","options":{"a":"The guest runs unmodified and the VMM translates the sensitive instructions.","b":"The CPU offers dedicated instructions that generate VM exits.","c":"The guest kernel is modified to make hypercalls to the hypervisor.","d":"The guest shares the host kernel, like a container."},"answer":"c","explanation":"Paravirtualization modifies the guest so that it explicitly invokes the hypervisor.","status":"ok"},{"id":"167","unit":"07","topic":"Virtualization techniques","text":"What does hardware-assisted virtualization allow?","options":{"a":"Dynamically translating the guest's binary code in software.","b":"Using CPU extensions (e.g. VT-x, AMD-V) for the guests.","c":"Assigning each VM a dedicated physical processor.","d":"Running modified guests that invoke the hypervisor with hypercalls."},"answer":"b","explanation":"The CPU extensions provide hardware support for the virtualization operations.","status":"ok"},{"id":"168","unit":"07","topic":"Virtualization techniques","text":"What does a VM exit cause in the hardware-assisted model?","options":{"a":"The shutdown of the VM and the release of its resources.","b":"The switch of the guest from kernel mode to user mode.","c":"The migration of the VM to another physical host.","d":"The transfer of control from the guest to the hypervisor."},"answer":"d","explanation":"A VM exit transfers control to the hypervisor when the guest causes an event that must be handled.","status":"ok"},{"id":"169","unit":"07","topic":"Types of virtualization","text":"Which goal does server virtualization describe?","options":{"a":"Separating an application from the operating system that runs it.","b":"Running several virtual servers on a shared physical infrastructure.","c":"Aggregating the disks of several devices into a single logical pool.","d":"Running the desktop of each user on a centralized VM."},"answer":"b","explanation":"Server virtualization consolidates several logical servers on a shared physical infrastructure.","status":"ok"},{"id":"170","unit":"07","topic":"Types of virtualization","text":"In the Virtual Desktop Infrastructure (VDI) model, where is the user's desktop run?","options":{"a":"In a container started on the user's device.","b":"On the user's PC, with the data synchronized on a server.","c":"On a VM hosted in the central infrastructure.","d":"In a session that shares the operating system of a server."},"answer":"c","explanation":"VDI runs the personal desktop in a central VM reached remotely.","status":"ok"},{"id":"171","unit":"07","topic":"Types of virtualization","text":"Which difference distinguishes Remote Desktop Services (RDS) from VDI in the slides?","options":{"a":"In RDS several user sessions share the same operating system.","b":"RDS runs the desktop on the client, VDI on the server.","c":"RDS virtualizes only applications, VDI only storage.","d":"RDS assigns each user a VM with its own operating system."},"answer":"a","explanation":"RDS can offer separate sessions sharing a single operating system instance.","status":"ok"},{"id":"172","unit":"07","topic":"Types of virtualization","text":"Which resource is abstracted in storage virtualization?","options":{"a":"The execution environment of individual applications, separated from the operating system.","b":"The RAM of the host, shared among the VMs.","c":"The configuration files and snapshots of the VMs.","d":"The capacity of several physical devices, presented as a logical resource."},"answer":"d","explanation":"Storage virtualization presents logical capacity abstracted from the underlying physical devices.","status":"ok"},{"id":"173","unit":"07","topic":"Types of virtualization","text":"What does application virtualization make possible?","options":{"a":"Running the user's desktop on a remote VM.","b":"Running several complete operating systems on the same server.","c":"Separating the application from the underlying operating system.","d":"Presenting several physical disks as a single logical volume."},"answer":"c","explanation":"Application virtualization separates the execution of the application from its direct installation in the underlying system.","status":"ok"},{"id":"174","unit":"07","topic":"Commercial hypervisors","text":"How are VMware ESX/ESXi classified in the slides?","options":{"a":"Microkernelized type 1 hypervisor.","b":"Monolithic type 1 hypervisor.","c":"Type 2 hypervisor.","d":"Container engine."},"answer":"b","explanation":"ESX/ESXi run bare metal (type 1) with a monolithic architecture.","status":"ok"},{"id":"175","unit":"07","topic":"Commercial hypervisors","text":"Which category does Microsoft Hyper-V belong to in the slides?","options":{"a":"Microkernelized type 1 hypervisor.","b":"Type 2 hypervisor.","c":"Container engine for Windows.","d":"Monolithic type 1 hypervisor."},"answer":"a","explanation":"Hyper-V is type 1 with a microkernelized design: the parent partition hosts drivers and management.","status":"ok"},{"id":"176","unit":"07","topic":"Commercial hypervisors","text":"What does KVM indicate in a Linux environment?","options":{"a":"A Microsoft hypervisor with a microkernelized architecture.","b":"A module that integrates virtualization into the Linux kernel.","c":"A container engine based on namespaces and cgroups.","d":"A purely software emulator that requires no hardware support."},"answer":"b","explanation":"KVM is a Linux kernel module that turns the kernel into a hypervisor (whether it is type 1 or 2 is debated).","status":"ok"},{"id":"177","unit":"07","topic":"Commercial hypervisors","text":"Which hardware support is required by the KVM implementation presented?","options":{"a":"CPU virtualization extensions (VT or AMD-V).","b":"A dedicated management partition, as in Hyper-V.","c":"A network card with SR-IOV support.","d":"A guest kernel modified for paravirtualization."},"answer":"a","explanation":"KVM uses the virtualization extensions of the processor.","status":"ok"},{"id":"178","unit":"07","topic":"VMs, hypervisors and VMM","text":"An administrator quickly creates three identical test environments from a ready VM. Which capability is being used?","options":{"a":"VM snapshot.","b":"Server consolidation.","c":"VM cloning.","d":"Live migration."},"answer":"c","explanation":"Cloning a VM replicates an already configured environment to quickly create test copies.","status":"ok"},{"id":"179","unit":"07","topic":"VMs, hypervisors and VMM","text":"If a VM tries to use memory that was not assigned to it, which component must control the access?","options":{"a":"The host kernel, through cgroups.","b":"The guest operating system.","c":"The application that generated the access.","d":"The hypervisor (VMM)."},"answer":"d","explanation":"The VMM controls memory accesses to enforce the isolation of the VMs.","status":"ok"},{"id":"180","unit":"08","topic":"Containers and VMs","text":"Why is a container generally lighter than a system VM?","options":{"a":"It uses a type 1 hypervisor that is lighter and more optimized than the one used by VMs.","b":"It shares the host kernel and isolates processes at the OS level.","c":"It runs the application without libraries or dependencies.","d":"It contains a reduced guest operating system, without drivers."},"answer":"b","explanation":"Containers share the host kernel and isolate processes, avoiding a guest system for each instance.","status":"ok"},{"id":"181","unit":"08","topic":"cgroups and namespaces","text":"Which Linux mechanisms underlie the isolation and resource control of containers?","options":{"a":"Hypervisor and VMM.","b":"Snapshots and virtual disks.","c":"Namespaces and cgroups.","d":"Hypercalls and VM exits."},"answer":"c","explanation":"Namespaces create isolated views; cgroups limit and account for resources.","status":"ok"},{"id":"182","unit":"08","topic":"cgroups and namespaces","text":"What are cgroups used for?","options":{"a":"Limiting and accounting for the resources used by groups of processes.","b":"Distributing container images among different hosts.","c":"Packaging an application together with its dependencies.","d":"Giving a group of processes an isolated view of the resources."},"answer":"a","explanation":"cgroups apply quotas and consumption measurements to groups of processes.","status":"ok"},{"id":"183","unit":"08","topic":"cgroups and namespaces","text":"What function do Linux namespaces perform?","options":{"a":"They give each container a kernel separate from the host one.","b":"They limit the CPU and memory usable by a group of processes.","c":"They define the instructions to build a container image.","d":"They give a group of processes an isolated view of a resource."},"answer":"d","explanation":"A namespace makes a process see only its own view of selected resources.","status":"ok"},{"id":"184","unit":"08","topic":"cgroups and namespaces","text":"A process in a container sees only a part of the host's processes. Which namespace is relevant?","options":{"a":"Mount namespace.","b":"UTS namespace.","c":"PID namespace.","d":"User namespace."},"answer":"c","explanation":"The PID namespace isolates the space of process identifiers visible to the container.","status":"ok"},{"id":"185","unit":"08","topic":"cgroups and namespaces","text":"Which namespace allows different containers to have separate network stacks and interfaces?","options":{"a":"Network namespace.","b":"IPC namespace.","c":"UTS namespace.","d":"PID namespace."},"answer":"a","explanation":"The network namespace separates interfaces, addresses and network stacks among containers.","status":"ok"},{"id":"186","unit":"08","topic":"cgroups and namespaces","text":"Why are cgroups and namespaces alone not a complete container platform?","options":{"a":"They offer no isolation of the network stack.","b":"Packaging and life-cycle management are missing.","c":"They do not allow limiting the resources of processes.","d":"They work only inside a virtual machine."},"answer":"b","explanation":"Distributing containers also requires images, packaging and life-cycle management tools.","status":"ok"},{"id":"187","unit":"08","topic":"cgroups and namespaces","text":"Which primitives does LXC use to create containers?","options":{"a":"A type 2 hypervisor and virtual disks.","b":"A separate guest kernel for each container.","c":"CPU hardware virtualization extensions.","d":"Linux kernel cgroups and namespaces."},"answer":"d","explanation":"LXC combines the cgroups and namespaces primitives offered by Linux.","status":"ok"},{"id":"188","unit":"08","topic":"Containers and VMs","text":"What is included in the packaging of an application container?","options":{"a":"The application and the kernel it must run on.","b":"Only the application code, without libraries.","c":"A complete operating system, kernel included.","d":"The application and its dependencies."},"answer":"d","explanation":"The container packages the application and its dependencies, so that its execution is repeatable.","status":"ok"},{"id":"189","unit":"08","topic":"Containers and VMs","text":"Which element do containers running on the same host share?","options":{"a":"The kernel of the host operating system.","b":"The same writable filesystem.","c":"The same network stack and the same IP address.","d":"The PID space, visible to all the containers."},"answer":"a","explanation":"Containers on the same host use the same kernel, while keeping other spaces isolated.","status":"ok"},{"id":"190","unit":"08","topic":"Containers and VMs","text":"Which limitation of containers compared with VMs is given in the slides?","options":{"a":"They have longer start-up times than VMs.","b":"The shared kernel offers weaker isolation than a VM.","c":"They require more memory per instance than a VM with the same workload.","d":"They cannot run on virtualized servers."},"answer":"b","explanation":"The shared kernel makes the isolation boundary different from that of a VM with its own guest kernel.","status":"ok"},{"id":"191","unit":"08","topic":"Containers and VMs","text":"Why can starting a container be faster than starting a VM?","options":{"a":"Its images are always smaller than 8 MB.","b":"It exploits CPU hardware extensions for start-up.","c":"It does not boot a complete guest operating system.","d":"It is run directly by the hypervisor."},"answer":"c","explanation":"Starting it does not require booting a complete guest operating system.","status":"ok"},{"id":"192","unit":"08","topic":"Microservices","text":"Which characteristic describes a monolithic application?","options":{"a":"Modules are released and scaled independently.","b":"Each function is deployed in a separate container.","c":"Functions are autonomous services that communicate over the network.","d":"Functions form a single, tightly integrated unit."},"answer":"d","explanation":"A monolith groups tightly integrated functions in a single deployment unit.","status":"ok"},{"id":"193","unit":"08","topic":"Microservices","text":"Which property is typical of microservices?","options":{"a":"Modules that must all be released together at every change.","b":"Services that must share the same process and database.","c":"Autonomous, loosely coupled services connected by interfaces.","d":"Tightly integrated components in a single process."},"answer":"c","explanation":"Microservices split the solution into autonomous services with communication interfaces.","status":"ok"},{"id":"194","unit":"08","topic":"Microservices","text":"Why are containers well suited to deploying microservices?","options":{"a":"Each service is deployed with its own dependencies.","b":"They guarantee stronger isolation than VMs.","c":"They force all the services to share the same libraries.","d":"They remove the need for network communication between services."},"answer":"a","explanation":"Each microservice can be deployed in a container together with its own dependencies.","status":"ok"},{"id":"195","unit":"08","topic":"Microservices","text":"In a network of containerized microservices, which problem grows with the number of instances?","options":{"a":"The need for services to communicate through IPC on the same host.","b":"Finding the endpoints of the services, which change over time.","c":"The size of the virtual disks to allocate.","d":"The number of kernels to boot for each instance."},"answer":"b","explanation":"With mobile and replicated instances, the endpoints change and must be discovered dynamically.","status":"ok"},{"id":"196","unit":"08","topic":"Kubernetes","text":"What function does a container orchestrator perform?","options":{"a":"It builds images from Dockerfiles.","b":"It schedules and manages containers on several nodes.","c":"It stores container images and distributes them to the nodes that request them.","d":"It isolates processes through namespaces and cgroups."},"answer":"b","explanation":"Orchestration decides where to run containers and governs their start, stop and replication.","status":"ok"},{"id":"197","unit":"08","topic":"Docker","text":"What role does Docker have in the ecosystem described?","options":{"a":"It is a lightweight hypervisor for virtual machines.","b":"It orchestrates containers on a cluster of several nodes.","c":"It provides tools to build images and run containers.","d":"It is the Linux kernel extension that introduces namespaces."},"answer":"c","explanation":"Docker offers the workflow for building images and running containers.","status":"ok"},{"id":"198","unit":"08","topic":"Docker","text":"What does a Dockerfile describe?","options":{"a":"The list of containers running on the host.","b":"The network configuration of a running container.","c":"The desired state of the replicas of an application.","d":"The instructions to build a Docker image."},"answer":"d","explanation":"The Dockerfile lists the reproducible steps to build an image.","status":"ok"},{"id":"199","unit":"08","topic":"Docker","text":"What is the relationship between a Docker image and a container?","options":{"a":"The image is the template from which a running container is created.","b":"Changes made in the container automatically end up in the image.","c":"At most one container at a time can be created from an image.","d":"The container is the template from which an image is generated."},"answer":"a","explanation":"The image is the immutable template from which an executable container is instantiated.","status":"ok"},{"id":"200","unit":"08","topic":"Docker","text":"What characteristic do the layers of a Docker image have?","options":{"a":"Each of them contains a different kernel.","b":"They are read-only and reusable across images.","c":"They are modified directly by each running container.","d":"They are copied in full into each new container."},"answer":"b","explanation":"Shareable layers reduce duplication and speed up distribution and building.","status":"ok"},{"id":"201","unit":"08","topic":"Docker","text":"What is a Docker registry used for?","options":{"a":"Storing and distributing container images.","b":"Registering the nodes of a Kubernetes cluster.","c":"Building images from Dockerfiles.","d":"Storing the state of the Kubernetes cluster."},"answer":"a","explanation":"A registry stores the images and makes them available to the hosts that must download them.","status":"ok"},{"id":"202","unit":"08","topic":"Kubernetes","text":"What is Kubernetes according to the slides?","options":{"a":"A container runtime that replaces Docker on individual hosts.","b":"A registry for distributing images.","c":"A platform for orchestrating containerized applications.","d":"A hypervisor that runs containers inside VMs."},"answer":"c","explanation":"Kubernetes automates the deployment and management of applications made of containers.","status":"ok"},{"id":"203","unit":"08","topic":"Kubernetes","text":"What elements is a Kubernetes cluster made of?","options":{"a":"A single node that runs both the Pods and the registry.","b":"A set of registries that distribute the images.","c":"A set of VMs managed by a common hypervisor.","d":"A control plane and worker nodes that run the workloads."},"answer":"d","explanation":"The cluster includes a control plane and worker nodes that run the workloads.","status":"ok"},{"id":"204","unit":"08","topic":"Kubernetes","text":"What is the smallest deployable unit in Kubernetes?","options":{"a":"A container.","b":"A Service.","c":"A Pod.","d":"A Deployment."},"answer":"c","explanation":"The Pod (one or more containers sharing network and storage) is the smallest unit created and scheduled by Kubernetes.","status":"ok"},{"id":"205","unit":"08","topic":"Kubernetes","text":"What is a Kubernetes Deployment used for?","options":{"a":"Defining which communications between Pods are allowed.","b":"Maintaining the desired number of replicas.","c":"Requesting persistent storage for a Pod.","d":"Exposing a set of Pods through a network endpoint that is stable over time."},"answer":"b","explanation":"The Deployment declares the desired number of replicas and helps maintain it.","status":"ok"},{"id":"206","unit":"08","topic":"Kubernetes","text":"A Deployment increases the replicas from two to four. Which result must the controller pursue?","options":{"a":"Creating new Pods until four replicas are reached.","b":"Creating four new Pods, for a total of six.","c":"Waiting for the administrator to create the missing Pods by hand.","d":"Restarting the two existing Pods with twice the resources."},"answer":"a","explanation":"The controller compares the actual and the desired state and creates the two missing replicas.","status":"ok"},{"id":"207","unit":"08","topic":"Kubernetes","text":"What function does a Kubernetes Service offer?","options":{"a":"Running the containers assigned to a node.","b":"Managing the number of replicas of an application.","c":"A persistent volume shared among the Pods.","d":"A stable endpoint to reach a set of Pods."},"answer":"d","explanation":"The Service exposes a stable endpoint even if the underlying Pods change.","status":"ok"},{"id":"208","unit":"08","topic":"Kubernetes","text":"What does the kubelet do on a worker node?","options":{"a":"It runs and monitors the Pods assigned to its node.","b":"It exposes the cluster APIs to kubectl.","c":"It stores the state of the whole cluster.","d":"It decides on which node to run each new Pod based on the available resources."},"answer":"a","explanation":"The kubelet runs and monitors the Pods of its own node; choosing the node is the scheduler's job, the state is in etcd and the APIs belong to the kube-apiserver.","status":"ok"},{"id":"209","unit":"08","topic":"Kubernetes","text":"Which Kubernetes object allows defining which communications between Pods are allowed?","options":{"a":"ReplicaSet.","b":"Service.","c":"Deployment.","d":"NetworkPolicy."},"answer":"d","explanation":"The NetworkPolicy defines the allowed flows between Pods according to selectors and network parameters.","status":"ok"},{"id":"210","unit":"08","topic":"Kubernetes","text":"Which component stores the state of the Kubernetes cluster?","options":{"a":"The kubelet of each node.","b":"The scheduler.","c":"Etcd.","d":"The kube-proxy."},"answer":"c","explanation":"Etcd stores the cluster state data used by the control plane.","status":"ok"},{"id":"211","unit":"08","topic":"Kubernetes","text":"If a container of a Pod fails, which Kubernetes capability steps in?","options":{"a":"Horizontal Pod Autoscaling.","b":"Self-healing according to the desired state.","c":"Live migration of the Pod to another node.","d":"Rolling update of the Deployment."},"answer":"b","explanation":"Self-healing restarts or replaces failed instances to bring the actual state back towards the desired one.","status":"ok"},{"id":"212","unit":"09","topic":"SDN concepts","text":"Which network plane forwards packets according to rules that have already been defined?","options":{"a":"Data plane.","b":"Control plane.","c":"Management plane.","d":"Application plane."},"answer":"a","explanation":"The data plane applies to packets decisions already translated into forwarding rules.","status":"ok"},{"id":"213","unit":"09","topic":"SDN concepts","text":"Which separation characterizes Software Defined Networking (SDN)?","options":{"a":"Separation of the data plane from the management plane.","b":"Separation of the control plane from the data plane.","c":"Separation of network functions from dedicated hardware.","d":"Separation of traffic into virtual networks (VLANs)."},"answer":"b","explanation":"SDN separates the control logic from the forwarding operations.","status":"ok"},{"id":"214","unit":"09","topic":"SDN concepts","text":"In the SDN model, what is the main task of the controller?","options":{"a":"It manages the life cycle of the VMs of the infrastructure.","b":"It forwards data packets between the switch ports.","c":"It decides the forwarding rules and installs them in the devices.","d":"It runs the virtualized network functions (VNFs)."},"answer":"c","explanation":"The controller computes the network decisions and installs rules in the devices.","status":"ok"},{"id":"215","unit":"09","topic":"SDN concepts","text":"What does the data plane of an SDN switch do for each packet?","options":{"a":"It recomputes the path with a distributed routing algorithm.","b":"It always forwards the packet to the controller for a decision.","c":"It floods the packet on all ports.","d":"It matches the packet against its rules and applies the action."},"answer":"d","explanation":"The switch matches the packet against the flow rules and applies the associated action.","status":"ok"},{"id":"216","unit":"09","topic":"SDN concepts","text":"Why can a global view of the network help the controller?","options":{"a":"It makes the southbound protocol unnecessary.","b":"It removes the need to install rules in the switches.","c":"It allows coordinated, consistent decisions across devices.","d":"It allows each switch to compute the paths autonomously."},"answer":"c","explanation":"The global view allows coordinated policies and choices on several nodes.","status":"ok"},{"id":"217","unit":"09","topic":"SDN concepts","text":"What does the big switch abstraction represent in the slides?","options":{"a":"A high-capacity physical switch that replaces the network core.","b":"A set of devices controlled as a single logical entity.","c":"A physically unique controller for the whole network.","d":"A VLAN extended to all the switches of the network."},"answer":"b","explanation":"The big switch is a logical abstraction: several physical devices appear as a network controlled as a unit.","status":"ok"},{"id":"218","unit":"09","topic":"SDN concepts","text":"How can a logically centralized control plane be implemented?","options":{"a":"By moving the control logic into the data plane.","b":"With an independent controller in each switch, without coordination.","c":"Necessarily with a single physical controller.","d":"With several coordinated physical controllers giving one logical view."},"answer":"d","explanation":"Logical centralization does not require a single physical controller; several controllers can cooperate.","status":"ok"},{"id":"219","unit":"09","topic":"SDN concepts","text":"Why must several SDN controllers synchronize their state?","options":{"a":"To keep consistent decisions across the network.","b":"To reduce the number of rules installed in the switches.","c":"To avoid switches having to contact the controller.","d":"To split the data traffic to be forwarded."},"answer":"a","explanation":"Synchronization keeps the decisions consistent when control is physically distributed.","status":"ok"},{"id":"220","unit":"09","topic":"SDN concepts","text":"What does the use of context in SDN policies allow?","options":{"a":"Defining rules valid for a single physical port.","b":"Installing all the rules proactively.","c":"Adapting decisions to traffic and network state.","d":"Doing without priorities among the rules."},"answer":"c","explanation":"The traffic and network context can influence the choice of the policy.","status":"ok"},{"id":"221","unit":"09","topic":"OpenFlow","text":"Which interaction does OpenFlow provide when a switch has no suitable rule?","options":{"a":"The switch asks the neighbouring switches for the rule.","b":"The switch computes a new permanent rule by itself.","c":"The switch always floods the packet on all ports.","d":"The switch can send the packet to the controller."},"answer":"d","explanation":"When a rule is missing, the switch can involve the controller with information about the packet.","status":"ok"},{"id":"222","unit":"09","topic":"OpenFlow","text":"What distinguishes the reactive management of flow rules?","options":{"a":"The rule is installed when a new flow is observed.","b":"The rules are installed before the traffic arrives.","c":"The rules never expire once installed.","d":"The switch modifies the rules without consulting the controller."},"answer":"a","explanation":"In reactive mode the rule is installed after a new flow is observed.","status":"ok"},{"id":"223","unit":"09","topic":"OpenFlow","text":"What characterizes the proactive installation of rules?","options":{"a":"The rules are removed as soon as the flow ends.","b":"The rules are installed before the traffic arrives.","c":"The switch generates the rules locally, without a controller.","d":"The rules are installed at the first packet of each flow."},"answer":"b","explanation":"In proactive mode the rules are already present when the expected traffic arrives.","status":"ok"},{"id":"224","unit":"09","topic":"OpenFlow","text":"Which trade-off concerns rules for very specific flows compared with aggregated rules?","options":{"a":"More granularity: finer control but more entries.","b":"Aggregated rules offer the finest control.","c":"Granularity does not affect the number of entries.","d":"More granularity reduces the number of entries in the flow table."},"answer":"a","explanation":"More specific rules allow fine control, but take up more table entries.","status":"ok"},{"id":"225","unit":"09","topic":"OpenFlow","text":"Which OpenFlow message can modify the entries of the flow table?","options":{"a":"FeaturesRequest.","b":"PacketOut.","c":"PacketIn.","d":"FlowMod."},"answer":"d","explanation":"FlowMod is the message with which the controller adds or modifies flow table entries.","status":"ok"},{"id":"226","unit":"09","topic":"OpenFlow","text":"Which elements typically make up a flow rule?","options":{"a":"Only the destination IP and the output port.","b":"The complete path computed by the controller.","c":"Match fields, actions, priority, counters, timeouts.","d":"The controller's address and the type of OpenFlow message."},"answer":"c","explanation":"A flow rule combines match criteria, actions and metadata such as priority and counters.","status":"ok"},{"id":"227","unit":"09","topic":"OpenFlow","text":"If several rules match a packet, which field helps choose the one that is applied?","options":{"a":"The order in which the rule was installed.","b":"The priority of the rule.","c":"The packet counter.","d":"The idle timeout."},"answer":"b","explanation":"The priority resolves the case where several rules match the same packet.","status":"ok"},{"id":"228","unit":"09","topic":"OpenFlow","text":"Which headers can the OpenFlow match shown be based on?","options":{"a":"On layer 2-4 fields and also layer 7 ones, such as the HTTP URL.","b":"On layer 2, 3 and 4 fields, also with wildcards.","c":"On layer 3 fields, but without wildcards.","d":"On the destination MAC address alone, like a traditional switch."},"answer":"b","explanation":"Match fields can concern Ethernet, IP and transport headers, also with wildcards.","status":"ok"},{"id":"229","unit":"09","topic":"OpenFlow","text":"Which action is provided by OpenFlow flow rules?","options":{"a":"Computing a new path towards the destination.","b":"Sending the packet to the controller, but not dropping it.","c":"Forwarding the packet on a port, without modifying its headers.","d":"Forwarding, dropping or modifying the packet."},"answer":"d","explanation":"Actions can forward, drop or modify fields and headers.","status":"ok"},{"id":"230","unit":"09","topic":"OpenFlow","text":"What is a timeout in a flow table used for?","options":{"a":"Limiting the bandwidth assigned to a flow.","b":"Delaying the forwarding of low-priority packets.","c":"Removing an entry after a fixed or idle time.","d":"Setting how often the switch contacts the controller."},"answer":"c","explanation":"Hard or idle timeouts automatically remove rules that are no longer useful.","status":"ok"},{"id":"231","unit":"09","topic":"SDN controller and APIs","text":"Which characteristic does the SDN controller have?","options":{"a":"It is software containing the network control logic.","b":"It is the component that forwards data packets.","c":"It is a standardized southbound protocol.","d":"It is a hardware ASIC integrated in each switch."},"answer":"a","explanation":"The controller is software that implements the control logic, separated from the data plane.","status":"ok"},{"id":"232","unit":"09","topic":"SDN controller and APIs","text":"Which interface connects the SDN controller to the data plane devices?","options":{"a":"Southbound API.","b":"Management interface (SNMP).","c":"Northbound API.","d":"East/West-bound API."},"answer":"a","explanation":"The southbound interface is the one between the controller and the forwarding devices.","status":"ok"},{"id":"233","unit":"09","topic":"SDN controller and APIs","text":"Which interface allows applications to express their needs to the controller?","options":{"a":"East/West-bound API.","b":"Management interface (SNMP).","c":"Northbound API.","d":"Southbound API."},"answer":"c","explanation":"Applications use the northbound interface to express requests to the controller.","status":"ok"},{"id":"234","unit":"09","topic":"Service Function Chain","text":"What is a Service Function Chain (SFC)?","options":{"a":"A chain of coordinated SDN controllers.","b":"An ordered sequence of network functions.","c":"A group of VNFs running on the same server.","d":"A set of OpenFlow rules with the same priority."},"answer":"b","explanation":"An SFC specifies in which order the traffic crosses the network functions.","status":"ok"},{"id":"235","unit":"09","topic":"Service Function Chain","text":"Which problem can a chain based on dedicated physical appliances have?","options":{"a":"Inability to process high-speed traffic.","b":"Need for an SDN controller for each appliance.","c":"Higher latency due to running in VMs.","d":"Wasted resources and slow reconfiguration."},"answer":"d","explanation":"Dedicated appliances can remain underused and make reconfiguration slow.","status":"ok"},{"id":"236","unit":"09","topic":"Service Function Chain","text":"In an SDN network, how can traffic be steered along an SFC?","options":{"a":"By letting distributed routing choose the best path.","b":"By merging all the functions into a single VNF.","c":"By physically rewiring the appliances at every change.","d":"With flow rules that steer packets between the functions."},"answer":"d","explanation":"With SDN, flow rules can steer packets between the functions of the chain.","status":"ok"},{"id":"237","unit":"09","topic":"NFV","text":"Which idea underlies Network Function Virtualization (NFV)?","options":{"a":"Using dedicated hardware for each network function.","b":"Network functions in software on standard hardware.","c":"Replacing all routers with OpenFlow switches.","d":"Separating the control plane from the data plane."},"answer":"b","explanation":"NFV implements network functions as software on standard hardware instead of dedicated appliances.","status":"ok"},{"id":"238","unit":"09","topic":"NFV","text":"What is a VNF?","options":{"a":"The set of physical and virtual resources of the NFV infrastructure.","b":"The component that manages the life cycle of the functions.","c":"A virtualized software instance of a network function.","d":"A hardware appliance dedicated to a network function."},"answer":"c","explanation":"A VNF is the software implementation of a network function on a virtualized infrastructure.","status":"ok"},{"id":"239","unit":"09","topic":"NFV","text":"What does the NFVI include?","options":{"a":"The compute, storage and network resources on which the VNFs run.","b":"The software of the individual network functions.","c":"The SDN controller that routes traffic between the VNFs.","d":"The component that orchestrates the network services."},"answer":"a","explanation":"The NFVI includes the compute, network and storage resources that support the execution of the VNFs.","status":"ok"},{"id":"240","unit":"09","topic":"NFV","text":"Which component manages the life cycle of a VNF?","options":{"a":"VNF Manager (VNFM).","b":"Virtualized Infrastructure Manager (VIM).","c":"NFV Orchestrator (NFVO).","d":"Controller SDN."},"answer":"a","explanation":"The VNF Manager handles the instantiation, update, scaling and termination of the VNFs.","status":"ok"},{"id":"241","unit":"09","topic":"NFV","text":"What role does the Virtualized Infrastructure Manager (VIM) have?","options":{"a":"It implements the packet forwarding logic.","b":"It manages the life cycle of the individual VNFs.","c":"It manages the virtualized resources of the NFVI.","d":"It coordinates the end-to-end network services."},"answer":"c","explanation":"The VIM administers the virtualized compute, network and storage resources.","status":"ok"},{"id":"242","unit":"09","topic":"NFV","text":"Which component coordinates the network services and the NFV resources overall?","options":{"a":"Virtualized Infrastructure Manager (VIM).","b":"NFVI.","c":"VNF Manager (VNFM).","d":"NFV Orchestrator (NFVO)."},"answer":"d","explanation":"The NFV Orchestrator coordinates the overall deployment and management of VNFs and NFVI.","status":"ok"},{"id":"243","unit":"09","topic":"NFV","text":"A software firewall is moved from a dedicated appliance to standard servers. Which concept describes the change?","options":{"a":"Software Defined Networking.","b":"Network Function Virtualization.","c":"Service Function Chaining.","d":"Virtual Desktop Infrastructure."},"answer":"b","explanation":"Moving the firewall from dedicated hardware to software on standard servers is a case of NFV.","status":"ok"},{"id":"244","unit":"10","topic":"Lab 1 – IPv6","text":"[Lab 1 – IPv6] On a Cisco router that has just been switched on, which command must be run before any other IPv6 configuration?","options":{"a":"no shutdown","b":"ipv6 address autoconfig","c":"ipv6 unicast-routing","d":"ipv6 route ::/0 <next-hop>"},"answer":"c","explanation":"ipv6 unicast-routing enables IPv6 globally, together with the forwarding of IPv6 packets, and must be the first IPv6 command.","status":"ok"},{"id":"245","unit":"10","topic":"Lab 1 – IPv6","text":"[Lab 1 – IPv6] What does the command ipv6 address autoconfig do on an interface of router R1?","options":{"a":"It joins the /64 prefix received in the RAs with its own interface ID.","b":"It asks a DHCPv6 server on the link for an address.","c":"It copies the prefix configured on the neighbouring router's interface without exchanging messages.","d":"It generates only the link-local address FE80::/64 of the interface."},"answer":"a","explanation":"It is stateless autoconfiguration: prefix (64 bits) from the RAs + interface ID (64 bits) generated locally.","status":"ok"},{"id":"246","unit":"10","topic":"Lab 1 – IPv6","text":"[Lab 1 – IPv6] How is the default route written in an ipv6 route command?","options":{"a":"::1/128","b":"::/0","c":"0.0.0.0/0","d":"FE80::/10"},"answer":"b","explanation":"::/0 is the zero-length prefix (default route); ::1/128 is the loopback, FE80::/10 is link-local, 0.0.0.0/0 is the IPv4 default route.","status":"ok"},{"id":"247","unit":"10","topic":"Lab 1 – IPv6","text":"[Lab 1 – IPv6] How does an IPv6 router choose the route when several entries match the destination?","options":{"a":"It uses the route that was configured first.","b":"It compares only the first 64 bits, i.e. the network prefix, and ignores the interface ID.","c":"It prefers the route with a link-local next hop.","d":"Longest prefix match on 128 bits, then metric or administrative distance."},"answer":"d","explanation":"As in IPv4 the longest prefix is chosen, but over 128 bits; among entries with the same prefix the metric and the administrative distance decide.","status":"ok"},{"id":"248","unit":"10","topic":"Lab 2 – VLAN","text":"[Lab 2 – VLAN] Why are the subinterfaces Fa0/0.2 and Fa0/0.3 created on the Fa0/0 interface of the one-arm router?","options":{"a":"To aggregate two physical links into a single, faster logical channel.","b":"Because each of them corresponds to an access port of the switch.","c":"Each handles the 802.1Q frames of one VLAN and has an IP of that network.","d":"To assign two addresses of the same IP network to the same interface."},"answer":"c","explanation":"encapsulation dot1q N binds the subinterface to VLAN N on the trunk; each subinterface acts as the gateway for the network of its VLAN.","status":"ok"},{"id":"249","unit":"10","topic":"Lab 2 – VLAN","text":"[Lab 2 – VLAN] During a ping between H2 (VLAN 2) and H3 (VLAN 3), some IP packets on the trunk seem to appear twice. Why?","options":{"a":"It crosses the trunk twice: to the router with tag 2, back with tag 3.","b":"The router retransmits the packets because a static route is missing.","c":"The switch sends every frame both with and without the tag.","d":"Spanning tree duplicates packets on trunk links for redundancy."},"answer":"a","explanation":"With the one-arm router, inter-VLAN traffic enters and leaves the same physical interface: the VLAN tag, the MACs and the TTL change.","status":"weak"},{"id":"250","unit":"10","topic":"Lab 2 – VLAN","text":"[Lab 2 – VLAN] Which default gateway must H2 (VLAN 2) and H3 (VLAN 3) use?","options":{"a":"Both the management address of switch SW-1.","b":"None, because the switch forwards the traffic between VLANs on its own.","c":"Both the address of the router's physical interface Fa0/0.","d":"The IP of the router subinterface of their own VLAN."},"answer":"d","explanation":"No IP should be assigned to the physical interface (it would only be needed for untagged traffic); the gateways are the IPs of the subinterfaces .2 and .3.","status":"ok"},{"id":"251","unit":"10","topic":"Lab 2 – VLAN","text":"[Lab 2 – VLAN] As an alternative to subinterfaces, an L2/L3 switch can route between VLANs using:","options":{"a":"Access ports configured on both VLANs at the same time.","b":"VLAN interfaces, each with an IP address.","c":"A trunk link towards each host.","d":"A separate spanning tree for each VLAN."},"answer":"b","explanation":"Multilayer switches create VLAN interfaces with an IP and route between them, in hardware or in the control CPU.","status":"ok"},{"id":"252","unit":"10","topic":"Lab 3 – Docker","text":"[Lab 3 – Docker] You start an alpine container, create test-file, exit and start a new container from the same image. Is test-file there?","options":{"a":"No: the changes made in the container do not go back into the image.","b":"No, because the filesystem of the alpine container is read-only.","c":"Yes, but only if the first container is still running.","d":"Yes: every change is saved automatically in the image."},"answer":"a","explanation":"Each container has its own writable layer on top of the (read-only) image: a new container starts again from the state of the image.","status":"ok"},{"id":"253","unit":"10","topic":"Lab 3 – Docker","text":"[Lab 3 – Docker] What does the option -p 8080:80 do in docker run?","options":{"a":"It publishes port 8080 of the container on port 80 of the host.","b":"It forwards port 80 of the host to port 8080 of all the containers.","c":"It publishes TCP port 80 of the container on port 8080 of the host.","d":"It opens port 8080 of the container without any mapping on the host."},"answer":"c","explanation":"The format is host:container; the service therefore answers on http://localhost:8080.","status":"ok"},{"id":"254","unit":"10","topic":"Lab 3 – Docker","text":"[Lab 3 – Docker] Why does the lab create a user-defined bridge network (docker network create)?","options":{"a":"To assign public IP addresses to the containers.","b":"To isolate the containers from the host kernel.","c":"Because on the default bridge network containers cannot communicate.","d":"Its advantages include automatic DNS resolution of container names."},"answer":"d","explanation":"The default bridge would work, but the user-defined one lets apache reach the database by the container's name.","status":"ok"},{"id":"255","unit":"10","topic":"Lab 3 – Docker","text":"[Lab 3 – Docker] Which docker run option mounts a host directory into the container, for example to make data persistent?","options":{"a":"-e","b":"-v","c":"-d","d":"-p"},"answer":"b","explanation":"-v <host>:<container>[:ro] mounts a volume or a directory; -p publishes ports, -e passes environment variables, -d starts in the background.","status":"ok"},{"id":"256","unit":"10","topic":"Lab 4 – Kubernetes","text":"[Lab 4 – Kubernetes] A Service of type NodePort:","options":{"a":"Exposes the Service only on an IP internal to the cluster.","b":"Requires an external load balancer provided by the cloud provider.","c":"Exposes it on a static port of each node (<NodeIP>:<NodePort>).","d":"Assigns each Pod a port of the node it runs on."},"answer":"c","explanation":"NodePort automatically also creates a ClusterIP; ClusterIP (the default) is reachable only from inside the cluster.","status":"ok"},{"id":"257","unit":"10","topic":"Lab 4 – Kubernetes","text":"[Lab 4 – Kubernetes] What is the default Service type in Kubernetes?","options":{"a":"LoadBalancer","b":"NodePort","c":"ExternalName","d":"ClusterIP"},"answer":"d","explanation":"ClusterIP exposes the Service on an IP internal to the cluster and is the default type.","status":"ok"},{"id":"258","unit":"10","topic":"Lab 4 – Kubernetes","text":"[Lab 4 – Kubernetes] You manually delete a Pod of a Deployment with 5 replicas. What happens?","options":{"a":"The Deployment creates a new Pod: it goes back to 5.","b":"The Deployment is deleted together with the Pod.","c":"The replicas stay at 4 until kubectl scale is run.","d":"The Pod is recreated only if the YAML file is applied again."},"answer":"a","explanation":"The control plane continuously reconciles the actual and the desired state (declarative approach).","status":"ok"},{"id":"259","unit":"10","topic":"Lab 4 – Kubernetes","text":"[Lab 4 – Kubernetes] To run MySQL keeping the data even if the Pod is deleted, the lab uses:","options":{"a":"A Service of type NodePort that keeps the data on the node.","b":"A StatefulSet with a PersistentVolumeClaim.","c":"A ConfigMap that contains the database files.","d":"A Deployment that saves the data in the container's filesystem."},"answer":"b","explanation":"Files in the container are ephemeral; the PVC (through volumeClaimTemplates and the local-path StorageClass) creates a PersistentVolume that survives the Pod.","status":"ok"},{"id":"260","unit":"10","topic":"Lab 4 – Kubernetes","text":"[Lab 4 – Kubernetes] In a container specification, what do requests and limits indicate?","options":{"a":"requests concerns memory, limits concerns CPU.","b":"requests: the maximum usable; limits: the minimum guaranteed to the container.","c":"Both tell the autoscaler how many replicas to create.","d":"requests: reserved and used to choose the node; limits: maximum cap."},"answer":"d","explanation":"The scheduler places the Pod based on the requests and the kubelet reserves them; the kubelet prevents the limits from being exceeded.","status":"ok"},{"id":"261","unit":"10","topic":"Lab 4 – Kubernetes","text":"[Lab 4 – Kubernetes] With kubectl autoscale deployment php-apache --cpu-percent=25 --min=1 --max=10, what does the HPA do?","options":{"a":"It adds a node to the cluster every time a Pod exceeds 25% CPU.","b":"It varies the replicas (1–10) to keep the average CPU of the Pods at 25%.","c":"It limits each Pod to 25% of the node's CPU.","d":"It reserves 25% of the CPU of each node for the application's Pods."},"answer":"b","explanation":"The HPA uses the metrics of the metrics server (metrics.k8s.io API) and scales the Deployment, not the nodes.","status":"ok"},{"id":"262","unit":"10","topic":"Lab 4 – Kubernetes","text":"[Lab 4 – Kubernetes] From which component does the Horizontal Pod Autoscaler get the CPU usage data?","options":{"a":"From the registry the image was downloaded from.","b":"From etcd, which records the consumption of each Pod.","c":"From the metrics server, through the metrics.k8s.io API.","d":"From the hypervisor that hosts the worker VMs."},"answer":"c","explanation":"Without the metrics server, the HPA (and kubectl top) have no metrics to use.","status":"ok"},{"id":"263","unit":"01","topic":"Addressing and subnetting","text":"Which of the following address/prefix pairs identifies a valid IP network?","options":{"a":"192.168.2.32/27","b":"192.168.3.0/23","c":"192.168.2.36/29","d":"192.168.12.0/21"},"answer":"a","explanation":"The network ID must have all host bits set to zero: 32 is a multiple of 32 (/27). 36 is not a multiple of 8 (/29), 3 is odd (/23), 12 is not a multiple of 8 (/21).","status":"ok"},{"id":"264","unit":"01","topic":"Addressing and subnetting","text":"An IP network must host 300 hosts. Which netmask wastes the fewest addresses?","options":{"a":"255.255.255.0","b":"255.255.254.0","c":"255.255.252.0","d":"255.255.255.128"},"answer":"b","explanation":"300 + 2 addresses are needed (network ID and broadcast): the smallest block has 512 addresses, i.e. /23 = 255.255.254.0 (exercise 1).","status":"ok"},{"id":"265","unit":"01","topic":"Addressing and subnetting","text":"According to the slides, in a classless addressing plan, what is the longest prefix usable for the point-to-point network between two routers?","options":{"a":"/32","b":"/31","c":"/30","d":"/29"},"answer":"c","explanation":"Every IP network must contain a network ID and a broadcast address: a /30 has 4 addresses, 2 for the routers. /31 is marked as not valid and 252 is the smallest usable netmask.","status":"ok"},{"id":"266","unit":"01","topic":"IPv4 routing and routing tables","text":"A router has the following routing table: 200.23.16.0/20 → interface 1; 200.23.18.0/23 → interface 2; 199.31.0.0/16 → interface 2. A packet destined to 200.23.19.5 is forwarded","options":{"a":"on interface 1, because 200.23.16.0/20 is the first matching entry in the table","b":"nowhere: it is discarded because it matches more than one entry","c":"on both interfaces, because two entries match","d":"on interface 2, because 200.23.18.0/23 is the most specific matching entry"},"answer":"d","explanation":"Both /20 (16.0-31.255) and /23 (18.0-19.255) match: the most specific one wins (longest prefix matching).","status":"ok"},{"id":"267","unit":"01","topic":"Addressing and subnetting","text":"The address 130.192.1.255 in the network 130.192.1.0/24 is:","options":{"a":"the directed broadcast address of that network","b":"the limited broadcast address, valid on any local network","c":"an address that can be assigned to a host","d":"the network ID of the network"},"answer":"a","explanation":"Host part all ones with a specific network ID: directed broadcast. The limited broadcast has all bits set to 1 (255.255.255.255).","status":"ok"},{"id":"268","unit":"01","topic":"IPv4 routing and routing tables","text":"In a router's routing table, the next hop of a static route to a remote network is:","options":{"a":"the address of the local interface the packet leaves from","b":"the address of the neighbouring router on the shared network","c":"the network ID of the destination network","d":"the broadcast address of the transit network"},"answer":"b","explanation":"In the example table, static routes (S) have the remote interface of the neighbouring router as next hop; direct routes (D) have the local interface.","status":"ok"},{"id":"269","unit":"01","topic":"Addressing and subnetting","text":"In classful addressing, which class does the address 150.10.20.30 belong to?","options":{"a":"Class A","b":"Class C","c":"Class B","d":"None: it is a multicast address"},"answer":"c","explanation":"First byte 128-191: class B.","status":"ok"},{"id":"270","unit":"01","topic":"Addressing and subnetting","text":"A router has the interface 192.168.1.1/28 and a server on the same link has 192.168.1.23/28, with default gateway 192.168.1.1. What happens?","options":{"a":"The server communicates normally, because it is on the same physical link as the router","b":"It works, because the router accepts any 192.168.1.x address","c":"The server reaches external destinations but not the local hosts","d":"The server cannot reach the gateway, which is in another /28 network"},"answer":"d","explanation":"With /28 the router is in 192.168.1.0/28 (hosts .1-.14) and the server in 192.168.1.16/28: the gateway is not on-link and the server cannot reach the outside (exercise 3).","status":"ok"},{"id":"271","unit":"01","topic":"Addressing and subnetting","text":"How many host-assignable addresses does a /26 network contain?","options":{"a":"62","b":"64","c":"30","d":"126"},"answer":"a","explanation":"A /26 has 64 addresses, minus network ID and broadcast: 62.","status":"ok"},{"id":"272","unit":"04","topic":"Spanning tree and loops","text":"Why can a loop in a network of bridges generate a broadcast storm that does not die out on its own?","options":{"a":"Switches regenerate broadcast frames when they update the filtering database","b":"Layer-2 frames have no time-to-live field","c":"Backward learning turns broadcasts into unicast frames","d":"Broadcast frames are retransmitted until an acknowledgement arrives"},"answer":"b","explanation":"The broadcast storm is due to the lack of a \"time-to-live\" in L2 frames; L3 networks tolerate transient loops thanks to the TTL.","status":"ok"},{"id":"273","unit":"04","topic":"Spanning tree and loops","text":"In a meshed LAN without spanning tree, which frames can loop?","options":{"a":"Unicast frames towards hosts already in the filtering database","b":"Only frames with CRC errors, which are not dropped","c":"Broadcast, multicast and frames towards unknown MACs","d":"802.1Q-tagged frames, because trunks have no filtering database"},"answer":"c","explanation":"The frames that are flooded loop: broadcast/multicast (very common) and frames towards stations that are not in the database.","status":"ok"},{"id":"274","unit":"04","topic":"Spanning tree and loops","text":"In a meshed LAN without spanning tree, which problem affects backward learning?","options":{"a":"Switches stop learning MAC addresses","b":"Switches learn destination MACs instead of source ones","c":"The filtering database contains only multicast addresses","d":"The port of a MAC in the database can keep changing"},"answer":"d","explanation":"With meshes the databases become inconsistent: an entry can change port indefinitely and never stabilize.","status":"ok"},{"id":"275","unit":"04","topic":"802.1Q, access and trunk ports","text":"Which values can the VLAN ID of user VLANs take in an IEEE 802.1Q tag, according to the slides?","options":{"a":"1-4094","b":"1-1024","c":"0-4095","d":"1-65535"},"answer":"a","explanation":"In the tag encoding, the possible VLAN ID values for the user are 1-4094.","status":"ok"},{"id":"276","unit":"04","topic":"802.1Q, access and trunk ports","text":"Why can a VLAN-unaware switch drop frames with an 802.1Q tag?","options":{"a":"Because the tag changes the source MAC address and the switch does not recognize it","b":"Because with the 4 bytes of the tag the frame can be too long","c":"Because the tag moves the Ethertype after the FCS field","d":"Because tagged frames are always broadcast frames"},"answer":"b","explanation":"The tagged frame is 4 bytes longer than the one generated by the host; VLAN-unaware switches do not accept tagged frames and can drop them if they are too large.","status":"ok"},{"id":"277","unit":"04","topic":"802.1Q, access and trunk ports","text":"Which method of assigning hosts to VLANs requires frames to be tagged directly by the stations?","options":{"a":"Port-based assignment","b":"Per-user assignment (802.1x)","c":"Cooperative assignment","d":"Transparent MAC-based assignment"},"answer":"c","explanation":"In cooperative assignment frames are tagged by the hosts (e.g. servers and routers on several VLANs, which use trunk ports).","status":"ok"},{"id":"278","unit":"04","topic":"VLANs","text":"When a router forwards a packet from one VLAN to another (e.g., a one-arm router), the frame sent on the destination VLAN","options":{"a":"keeps the original L2 header and only changes the VLAN tag","b":"is sent in broadcast, since the destination is in another VLAN","c":"keeps the MAC address of the original sender as source","d":"has a new L2 header, with different MAC addresses"},"answer":"d","explanation":"Between VLANs an L3 device is needed: the original L2 header is discarded and a new one is created, with different source and destination MACs.","status":"ok"},{"id":"279","unit":"02","topic":"Routing concepts","text":"In the routing slides, MPLS is cited as an example of which \"on-the-fly\" forwarding algorithm?","options":{"a":"Label swapping","b":"Source routing","c":"Routing by network address","d":"Backward learning"},"answer":"a","explanation":"The on-the-fly algorithms listed are routing by network address, label swapping (e.g. MPLS) and source routing.","status":"ok"},{"id":"280","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"In a Router Advertisement message, the M flag set to 1 indicates that:","options":{"a":"only information other than the address, such as DNS, comes from DHCPv6","b":"addresses are available through DHCPv6 (stateful configuration)","c":"the host must generate the interface ID from the MAC (EUI-64)","d":"the announced prefix is deprecated and must be replaced"},"answer":"b","explanation":"M (Managed Address Configuration) = 1: address available through DHCP; the O flag concerns the other information, e.g. the DNS server.","status":"ok"},{"id":"281","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"With M = 0 and O = 1 in the Router Advertisement, how does an IPv6 host configure itself?","options":{"a":"It gets the address and DNS from a DHCPv6 server","b":"It uses only the link-local address, without contacting any server","c":"It takes the address from the RA prefix and the rest from DHCPv6","d":"It waits for the administrator to configure the address manually"},"answer":"c","explanation":"This is the hybrid configuration (stateless DHCP): address from the RA prefix, other information through DHCP.","status":"ok"},{"id":"282","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"To which address does a DHCPv6 client send the Solicit message?","options":{"a":"FF02::1, all nodes on the link","b":"FF02::2, all routers on the link","c":"The unicast address of the default gateway","d":"FF02::1:2, all DHCP agents"},"answer":"d","explanation":"Solicit and Request are sent to the all-agents address FF02::1:2.","status":"ok"},{"id":"283","unit":"03","topic":"Autoconfiguration and DHCPv6","text":"What characterizes the stateful configuration of an IPv6 host?","options":{"a":"All information, address included, comes from DHCP","b":"The interface ID is generated locally and the prefix comes from the router","c":"The address is configured manually by the administrator","d":"The host uses only the link-local address"},"answer":"a","explanation":"Stateful: all information from DHCP. Stateless: self-generated interface ID and prefix from the router.","status":"ok"},{"id":"284","unit":"03","topic":"Neighbor Discovery","text":"To which address is an ICMPv6 Router Solicitation message sent?","options":{"a":"FF02::1:2, the all-DHCP-agents multicast","b":"FF02::2, the all-routers multicast","c":"The solicited-node multicast of the router","d":"In broadcast over the whole link"},"answer":"b","explanation":"The Router Solicitation is sent to the all-routers multicast address FF02::2.","status":"ok"},{"id":"285","unit":"03","topic":"IPv6 addresses","text":"A packet sent to an IPv6 anycast address is delivered:","options":{"a":"to all the interfaces that have that address, like a multicast","b":"to an interface chosen at random by the sender","c":"to the \"nearest\" interface with that address","d":"to the interface with the lowest MAC address"},"answer":"c","explanation":"The packet is routed towards the \"nearest\" of the interfaces with that address, according to the routing table.","status":"ok"},{"id":"286","unit":"03","topic":"IPv6 addresses","text":"Which statement about IPv6 anycast addresses is consistent with the slides?","options":{"a":"They can be assigned to only one interface per link","b":"They replace the IPv4 broadcast in Neighbor Discovery","c":"They were initially designed for DHCPv6","d":"The same address can be assigned to several devices"},"answer":"d","explanation":"An anycast address can be assigned to several interfaces, typically of different devices; it was born for DNS and is still experimental.","status":"ok"},{"id":"287","unit":"05","topic":"Delay and jitter","text":"In the slides, jitter is defined as:","options":{"a":"the variability of the delay","b":"the average end-to-end delay across the network","c":"the percentage of lost packets","d":"the time to transmit a packet on the link"},"answer":"a","explanation":"\"Jitter = delay variability\": streaming requires low jitter, i.e. a constant delay.","status":"ok"},{"id":"288","unit":"05","topic":"Delay and jitter","text":"How can an end system compensate for the jitter of a multimedia flow?","options":{"a":"By asking for the retransmission of packets that arrived late","b":"By delaying every data unit up to the maximum delay","c":"By reducing the packet size at every delay variation","d":"By marking packets with a higher-priority DiffServ class"},"answer":"b","explanation":"Countermeasure in the end systems: every data unit is brought to the maximum delay, so the end-to-end delay increases.","status":"ok"},{"id":"289","unit":"05","topic":"Delay and jitter","text":"For which applications is compensating jitter with an additional delay most critical?","options":{"a":"Transfer of large files","b":"One-way streaming of recorded videos","c":"Interactive ones, such as telephony and games","d":"E-mail and messaging"},"answer":"c","explanation":"Increasing the end-to-end delay is critical for interactive applications (telephony, conferencing, games, virtual reality).","status":"ok"},{"id":"290","unit":"05","topic":"Delay and jitter","text":"According to the slides, for verbal interaction the one-way delay should be below","options":{"a":"10-15 ms","b":"1-1.5 s","c":"400-500 ms","d":"100-150 ms"},"answer":"d","explanation":"Interactivity: for verbal interaction the one-way delay must stay below 100-150 ms.","status":"ok"}]};
